import type { Response,  } from '@/type'
import { post,  } from '../../../services/api-2'





export interface SkriningPasien {
    id:               number;
    cara_datang:      string;
    asal_rujuk:       string;
    hari:             string;
    tanggal:          string;
    jam_datang:       string;
    jam_registrasi:   string;
    surat_pengantar:  string;
    nama_pengantar:   string;
    alamat_pengantar: string;
    keluhan_utama:    string;
    penyakit:         string;
    rekomendasi:      string;
    tujuan_awal:      string;
    petugas_skrining: PetugasSkrining;
}

export interface PetugasSkrining {
    nama: string;
    ttd:  string;
}




const getSkriningPasien = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<SkriningPasien[]>> => {
    const response = await post(`/v1/skrining-pasien/get`, { no_reg: noreg })

  return response.data
}

export { getSkriningPasien }
