import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { getFormulirManager } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextField } from './text-field'

interface ReportFormulirManagerProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportFormulirManager({
  isReport = false,
  no = '',
  noreg = '',
}: ReportFormulirManagerProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.formulirManager, noreg],
    queryFn: () => getFormulirManager(noreg),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const pelayananPasien = result?.pelayanan_pasien
  const pelayanan = result?.pelayanan ?? []
  const catatan = result?.catatan ?? []

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR MANAJER PELAYANAN PASIEN
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {/* Pelayanan Pasien */}
        <div className='p-2 border border-black space-y-2.5 mb-4'>
          <TextField title='MPP oleh' value={pelayananPasien?.nama_mpp} />
          <TextField title='Ruangan' value={pelayananPasien?.ruangan} />
          <TextField title='Kelas' value={pelayananPasien?.kelas} />
          <TextField title='DPJP' value={pelayananPasien?.dpjp} />
          <TextField
            title='Dokter Konsultan Lain'
            value={pelayananPasien?.dokter_konsultan_lain}
          />
          <TextField
            title='Skrining Pasien'
            value={pelayananPasien?.skrining_pasien}
          />
          <TextField
            title='Asesmen Pasien'
            value={pelayananPasien?.asesmen_pasien}
          />
          <TextField
            title='Dokter Konsulen 1'
            value={result?.dokter_konsul_satu}
          />
          <TextField
            title='Dokter Konsulen 2'
            value={result?.dokter_konsul_dua}
          />
          <TextField
            title='Dokter Konsulen 3'
            value={result?.dokter_konsul_tiga}
          />
        </div>

        {/* Perencanaan Manajemen Pelayanan Pasien */}
        <h2 className='text-center text-black font-semibold mb-2'>
          PERENCANAAN MANAJEMEN PELAYANAN PASIEN
        </h2>
        <div className='mb-4'>
          <div className='flex'>
            <SimpleColumn
              head
              name='NO'
              className='w-[40px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='TANGGAL'
              className='p-1 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='IDENTIFIKASI MASALAH'
              className='p-1 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='PERENCANAAN (PM)'
              isLast
              className='p-1 flex-1'
              className2='text-[10px]'
            />
          </div>
          {pelayanan.map((item, i) => (
            <div key={i} className='flex'>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[40px] p-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.tanggal}
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.identifikasi_masalah}
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.pmpp}
                isLast
                className='p-1 flex-1'
                className2='text-[10px]'
              />
            </div>
          ))}
          {pelayanan.length === 0 && (
            <p className='text-center text-xs p-2'>Tidak ada data</p>
          )}
        </div>

        {/* Catatan Implementasi */}
        <h2 className='text-center text-black font-semibold mb-2'>
          CATATAN IMPLEMENTASI MPP
        </h2>
        <div className='mb-2'>
          <div className='flex'>
            <SimpleColumn
              head
              name='NO'
              className='w-[40px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='TANGGAL & JAM'
              className='p-1 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='CATATAN IMPLEMENTASI'
              isLast
              className='p-1 flex-1'
              className2='text-[10px]'
            />
          </div>
          {catatan.map((item, i) => (
            <div key={i} className='flex'>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[40px] p-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.tanggal}
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.catatan}
                isLast
                className='p-1 flex-1'
                className2='text-[10px]'
              />
            </div>
          ))}
          {catatan.length === 0 && (
            <p className='text-center text-xs p-2'>Tidak ada data</p>
          )}
        </div>
      </div>
    </LayoutBorderNo>
  )
}
