import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'
import clsx from 'clsx'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { TandaTangan } from '@/components/tanda-tangan'
import { Button } from '@/components/ui/button'
import { formatTanggalV2, formatTanggalV3 } from '@/helper/date'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { SkriningPasien, getSkriningPasien } from './skrining'

interface SkriningProps {
  isReport?: boolean
  noreg?: string

  no?: string
}

export function ReportSkringPasien({
  isReport = false,
  noreg = '',

  no = '',
}: SkriningProps) {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.skriningPasien, noreg],
    queryFn: () => getSkriningPasien({ noreg }),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  const selected = result[index]

  const Selected = ({ data }: { data: SkriningPasien }) => {
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <div className='flex items-center justify-center border-r border-foreground p-4 text-center text-2xl font-bold'>
            FORMULIR SKRINING PASIEN
          </div>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien ?? ''}
              noRM={pasien?.no_rm ?? ''}
              ruangan={pasien.bagian ?? ''}
              tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
              jk={pasien.jenis_kelamin ?? ''}
            />
          )}
          {/* Informasi Pasien */}
        </div>

        <div className='px-2 pb-2'>
          <p className='text-xs text-black mb-1'>
            Tanggal : {formatTanggalV2(data.tanggal)}
          </p>

          <div className='mt-3 border-2 border-foreground'>
            {/* Judul + Identitas */}
            {/* Cara datang / Asal rujukan / Hari Tanggal */}
            <div className='grid grid-cols-[1fr_1.4fr_1.6fr] border-b border-foreground'>
              <div className='border-r border-foreground p-2'>
                <div className='pb-2'>Cara datang :</div>
                {['Sendiri', 'Keluarga', 'Ambulance', 'Polisi', 'Penolong'].map(
                  (c) => (
                    <Check
                      key={c}
                      label={c}
                      checked={has(data.cara_datang, c)}
                    />
                  )
                )}
              </div>
              <div className='border-r border-foreground p-2'>
                <div className='pb-1'>Asal Rujukan :</div>
                <DotLine value={data.asal_rujuk} className='mb-6' />
                <div className='pb-1'>Surat Pengantar :</div>
                <DotLine value={data.surat_pengantar} />
                <div className='pt-1 text-center italic'>
                  (dari dokter internal)
                </div>
              </div>
              <div>
                <div className='border-b border-foreground p-2'>
                  <div className='pb-1'>Hari/ Tanggal</div>
                  <DotLine value={`${data.hari} / ${data.tanggal}`} />
                </div>
                <div className='grid grid-cols-2'>
                  <div className='border-r border-foreground p-2'>
                    <div className='pb-1'>Jam datang :</div>
                    <DotLine value={data.jam_datang} />
                  </div>
                  <div className='p-2'>
                    <div className='pb-1'>Jam Registrasi :</div>
                    <DotLine value={data.jam_registrasi} />
                  </div>
                </div>
              </div>
            </div>

            {/* Nama Pengantar / Keluhan Utama */}
            <div className='grid grid-cols-[1fr_3fr] border-b border-foreground'>
              <div className='border-r border-foreground p-2'>
                <div className='pb-1'>Nama Pengantar :</div>
                <DotLine value={data.nama_pengantar} />
              </div>
              <div className='p-2'>
                <div className='pb-1'>Keluhan Utama :</div>
                <DotLine value={data.keluhan_utama} />
              </div>
            </div>

            {/* Alamat Pengantar / Penyakit / Rekomendasi */}
            <div className='grid grid-cols-[1fr_3fr] border-b border-foreground'>
              <div className='border-r border-foreground p-2'>
                <div className='pb-1'>Alamat Pengantar :</div>
                {data.alamat_pengantar.split('\n').map((line, i) => (
                  <DotLine key={i} value={line} className='mb-4' />
                ))}
                <DotLine value='' />
                <DotLine value='' className='mt-4' />
              </div>
              <div>
                <div className='grid grid-cols-3 border-b border-foreground p-2'>
                  <div>
                    <Check
                      label='Trauma'
                      checked={
                        has(data.penyakit, 'Trauma') &&
                        !has(data.penyakit, 'Non')
                      }
                    />
                    <Check
                      label='Non Trauma'
                      checked={has(data.penyakit, 'Non Trauma')}
                    />
                    <Check
                      label='Obstetri'
                      checked={has(data.penyakit, 'Obstetri')}
                    />
                  </div>
                  <div>
                    <Check
                      label='Nyeri dada'
                      checked={has(data.penyakit, 'Nyeri dada')}
                    />
                    <Check
                      label='Luka Terbuka'
                      checked={has(data.penyakit, 'Luka Terbuka')}
                    />
                    <Check
                      label='Kesakitan/ Kejang'
                      checked={has(data.penyakit, 'Kejang')}
                    />
                  </div>
                  <div>
                    <Check
                      label='Sesak Nafas'
                      checked={has(data.penyakit, 'Sesak')}
                    />
                  </div>
                </div>
                <div className='p-2'>
                  <div className='pb-1'>Rekomendasi :</div>
                  <div className='flex flex-wrap items-center gap-x-8 gap-y-1'>
                    {['IGD', 'PONEK', 'Poliklinik', 'HD'].map((r) => (
                      <Check
                        key={r}
                        label={r}
                        checked={has(data.rekomendasi, r)}
                      />
                    ))}
                    <div className='flex items-center gap-2'>
                      <Box
                        checked={
                          !['IGD', 'PONEK', 'Poliklinik', 'HD'].some((r) =>
                            has(data.rekomendasi, r)
                          ) && !!data.rekomendasi
                        }
                      />
                      <span>DLL</span>
                      <DotLine
                        value={
                          ['IGD', 'PONEK', 'Poliklinik', 'HD'].some((r) =>
                            has(data.rekomendasi, r)
                          )
                            ? ''
                            : data.rekomendasi
                        }
                        className='w-40'
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Tujuan awal / Petugas Skrining */}
            <div className='grid grid-cols-[1.2fr_2.8fr]'>
              <div className='border-r border-foreground p-2'>
                <div className='pb-2'>Tujuan awal Pasien :</div>
                {[
                  'Periksa (kasus baru)',
                  'Kontrol',
                  'Check Laboratorium',
                  'Rawat inap',
                ].map((t) => (
                  <div className='pb-3' key={t}>
                    <Check label={t} checked={has(data.tujuan_awal, t)} />
                  </div>
                ))}
              </div>
              <div className='flex flex-col items-center p-2'>
                <div className='pb-6 text-lg'>Petugas Skrining</div>
                <div className='flex-1' />
                {data.petugas_skrining.ttd ? (
                  <TandaTangan
                    imageSrc={
                      data.petugas_skrining.ttd != ''
                        ? `${import.meta.env.VITE_BASE_API_URL}/app/images/skrining_pasien/${data.petugas_skrining.ttd}`
                        : undefined
                    }
                    className='flex-[0.5]'
                  />
                ) : (
                  <div className='h-20' />
                )}
                <div className='pt-2'>
                  ({' '}
                  {data.petugas_skrining.nama ||
                    '................................'}{' '}
                  )
                </div>
                <div className='pb-2 text-lg'>Nama Terang dan Tanda Tangan</div>
              </div>
            </div>
          </div>
        </div>
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {result.length > 0 &&
        result.map((item, idx) => (
          <Button
            className={clsx(index == idx && 'bg-green-500 text-white m-4')}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {formatTanggalV2(item.tanggal)}
          </Button>
        ))}

      {selected != null ? <Selected data={selected} /> : null}
    </>
  )
}

function Box({ checked }: { checked: boolean }) {
  return (
    <span className='inline-flex h-4 w-4 shrink-0 items-center justify-center border border-foreground align-middle'>
      {checked ? (
        <span className='text-sm leading-none font-bold'>✓</span>
      ) : null}
    </span>
  )
}

function Check({ label, checked }: { label: string; checked: boolean }) {
  return (
    <div className='flex items-center gap-2 py-0.5'>
      <Box checked={checked} />
      <span>{label}</span>
    </div>
  )
}

function DotLine({
  value,
  className = '',
}: {
  value?: string
  className?: string
}) {
  return (
    <div
      className={`border-b border-dotted border-muted-foreground pb-0.5 ${className}`}
      style={{ minHeight: '1.4rem' }}
    >
      {value || '\u00A0'}
    </div>
  )
}

const has = (list: string, item: string) =>
  list
    .toLowerCase()
    .split(/[,;]/)
    .map((s) => s.trim())
    .some((s) => s === item.toLowerCase() || s.includes(item.toLowerCase()))
