import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { getMonitoringCairan } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportMonitoringCairanProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportMonitoringCairan({
  isReport = false,
  no = '',
  noreg = '',
}: ReportMonitoringCairanProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.monitoringCairan, noreg],
    queryFn: () => getMonitoringCairan(noreg),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null
  const intake = result?.intake ?? []
  const output = result?.out_put ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          MONITORING CAIRAN IN TAKE DAN OUT PUT
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {/* CAIRAN INTAKE */}
        <h2 className='text-center text-black font-semibold mb-2'>
          CAIRAN INTAKE
        </h2>
        <div className='mb-4'>
          <div className='flex'>
            <SimpleColumn
              head
              name='No.'
              className='w-[30px] p-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Tanggal / Jam'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Minum'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='NGT'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Infus'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Jumlah'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Perawat'
              isLast
              className='p-1 flex-1'
              className2='text-[9px]'
            />
          </div>
          {intake.map((item, i) => (
            <div key={item.id ?? i} className='flex'>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[30px] p-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.insert_dttm}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.minum}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.ngt}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.infuse}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.total}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.perawat?.nama}
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
          ))}
          {intake.length === 0 && (
            <p className='text-center text-xs p-2'>Tidak ada data</p>
          )}
        </div>

        {/* CAIRAN OUT PUT */}
        <h2 className='text-center text-black font-semibold mb-2'>
          CAIRAN OUT PUT
        </h2>
        <div className='mb-2'>
          <div className='flex'>
            <SimpleColumn
              head
              name='No.'
              className='w-[30px] p-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Tanggal / Jam'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Urine'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='NGT'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='WSD'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Drain'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Muntah'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Pendarahan'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Jumlah'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Perawat'
              isLast
              className='p-1 flex-1'
              className2='text-[9px]'
            />
          </div>
          {output.map((item, i) => (
            <div key={item.id ?? i} className='flex'>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[30px] p-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.insert_dttm}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.urine}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.ngt}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.wsd}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.drain}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.muntah}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.pendarahan}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.total}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={item.perawat?.nama}
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
          ))}
          {output.length === 0 && (
            <p className='text-center text-xs p-2'>Tidak ada data</p>
          )}
        </div>
      </div>
    </LayoutBorderNo>
  )
}
