import QRCode from 'react-qr-code'

import { cn } from '@/lib/utils'

interface TandaTanganProps {
  /** URL gambar tanda tangan. Jika kosong, fallback ke QR code dari `name`. */
  imageSrc?: string
  /** Nama yang ditampilkan di bawah gambar tanda tangan. */
  name?: string
  className?: string
  imageClassName?: string
  size?: number
}

export function TandaTangan({
  imageSrc,
  name = '',
  className,
  imageClassName,
  size = 60,
}: TandaTanganProps) {
  return (
    <div
      className={cn(
        'flex flex-col items-center gap-1 justify-center',
        className
      )}
    >
      {imageSrc ? (
        <img
          src={imageSrc}
          alt='tanda tangan'
          width={size}
          height={size}
          className={cn('h-[60px] w-[60px] object-contain', imageClassName)}
        />
      ) : (
        <QRCode
          value={name !== '' ? name : '-'}
          className={cn('h-[60px] w-[60px]', imageClassName)}
        />
      )}

      {name !== '' && <p className='text-xs text-center text-black'>{name}</p>}
    </div>
  )
}
