import { ReactNode } from 'react'
import QRCode from 'react-qr-code'

import { cn } from '@/lib/utils'

interface SimpleColumnPPAProps {
  name?: string
  namePPA?: string
  isLast?: boolean
  head?: boolean
  className?: string
  className2?: string
  hasQR?: boolean
  isChild?: ReactNode
  height?: string
}

export function SimpleColumnPPA({
  name,
  namePPA,
  head,
  isLast,
  className = 'flex-1',
  className2 = '',
  hasQR = false,
  isChild,
  height,
}: SimpleColumnPPAProps) {
  if (isChild)
    return (
      <div
        className={cn(
          'flex flex-col gap-2 text-center justify-center items-center p-2 border-y border-black border-l',
          isLast && 'border-r',
          className,
          head && 'bg-gray-100'
        )}
      >
        {isChild}
      </div>
    )

  return (
    <div
      className={cn(
        'flex flex-col gap-2 text-center justify-center items-center p-2 border-y border-black border-l',
        isLast && 'border-r',
        className,
        head && 'bg-gray-100'
      )}
    >
      {namePPA != '' ? <p className={cn(className2)}>{namePPA}</p> : null}
      {hasQR && (
        <QRCode value={name!} className={height ?? 'h-[50px] w-[50px]'} />
      )}
      {name != '' ? <p className={cn(className2)}>{name}</p> : null}
    </div>
  )
}
