import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { getTindakanPembiusan } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportTindakanPembiusanProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportTindakanPembiusan({
  isReport = false,
  no = '',
  noreg = '',
}: ReportTindakanPembiusanProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.tindakanPembiusan, noreg],
    queryFn: () => getTindakanPembiusan(noreg),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        {/* Header: judul kiri + info pasien kanan */}
        <div className='border border-black mb-4'>
          <div className='flex'>
            <div className='w-1/2 flex items-center justify-center p-3'>
              <h1 className='text-center text-black font-semibold text-sm leading-tight'>
                PERSETUJUAN
                <br />
                TINDAKAN PEMBIUSAN
              </h1>
            </div>
            <div className='w-1/2 border-l border-black p-2 space-y-1'>
              <p className='text-xs'>
                Nama Pasien : {pasien?.nama_pasien ?? ''}
              </p>
              <p className='text-xs'>
                Tanggal Lahir :{' '}
                {formatTanggalV3(pasien?.tanggal_lahir ?? '') ?? ''}
              </p>
              <p className='text-xs'>
                Nomor Rekam Medis : {pasien?.no_rm ?? ''}
              </p>
            </div>
          </div>
        </div>

        {/* I. PERSETUJUAN */}
        <div className='bg-black px-2 py-0.5 mb-2'>
          <p className='text-white font-bold text-[10px]'>
            I.&nbsp;&nbsp;&nbsp;&nbsp;PERSETUJUAN
          </p>
        </div>
        <p className='text-xs text-black mb-3 px-2'>
          Bersama ini saya : {result?.bersama_ini_saya} meminta persetujuan dan
          wewenang untuk melakukan {result?.pembiusan} nerve bloc untuk prosedur{' '}
          {result?.prosedur} <br />
          Adapun alternative untuk pembiusan adalah :{' '}
          {result?.alternative_pembiusan}
        </p>

        {/* II. RESIKO DAN METODE ALTERNATIF */}
        <div className='bg-black px-2 py-0.5 mb-2'>
          <p className='text-white font-bold text-[10px]'>
            II.&nbsp;&nbsp;&nbsp;&nbsp;RESIKO DAN METODE ALTERNATIF
          </p>
        </div>
        <div className='text-xs text-black space-y-1.5 px-2 mb-3'>
          <p>
            1. Saya menyadari bahwa pelayanan dirumah sakit ini merupakan suatu
            pelayanan tim (termasuk dokter dan perawat anastesi) dan bahwasannya
            anastesi untuk tindakan operasi ini akan dilakukan dibawah
            pengawasan : {result?.pengawasan}
          </p>
          <p>
            2. Saya menyadari dan mengerti sepenuhnya penjelasan dokter
            spesialis anastersi bahwa jenis pembiusan apupun yang dilakukan
            selalu mengandung beberapa konsekuensi dan resiko. Resiko potensi
            yang mungkin terjadi termasuk tekanan darah, reaksi obat, (alergi)
            henti jantung , kerusakan otak, kelumpuhan, kerusakan saraf bahkan
            kematian. Saya menyadari hal ini dan resiko serta komplikasi lain
            yang juga mungkin dapat terjadi.
          </p>
          <p>
            3. Saya menyadari dan mengerti bahwa dalam praktek kedokteran, bukan
            merupakan ilmu pengetahuan yang pasti dan saya menyadari tidak
            seoran pun dapat menjanjikan atau menjamin sesuatu yang berhubungan
            dengan tindakan medis termasuk pembiusan.
          </p>
          <p>
            4. Saya menyadari dan mengerti bahwa bat-obatan yang saya dapatkan
            sebelum prosedur pembedahan dan pembiusan dapat saja menimulkan
            komplikasi bagi pembiusan dan pembedahan. Oleh karena itu
            sudahmenjadi kewajiban dan tanggung jawab saya untuk memberikan
            informasi kepada dokter semua obat-obatan yang saya minum termasuk
            aspirin, kontraspsin, obat-obatan flu, narkotik, marijuana, kokain
            dan lain-lain.
          </p>
          <p>
            5. Saya sudah membaca formulir ini secara teliti, dan menyetujui
            pembuatan tentang tindakan yang dilakukan termasuk kemungkinan
            komplikasi-komplikasi yang mungkin terjadi, oleh sebabitu saya
            menyatakan mengerti isi dan menerima sersyaratan yang tercantum.
          </p>
        </div>

        {/* III. KOMPLIKASI */}
        <div className='bg-black px-2 py-0.5 mb-2'>
          <p className='text-white font-bold text-[10px]'>
            III.&nbsp;&nbsp;&nbsp;&nbsp;KOMPLIKASI, KONDISI, YANG TERDUGA DAN
            HASIL YANG DI PEROLEH
          </p>
        </div>
        <div className='text-xs text-black space-y-1.5 px-2 mb-3'>
          <p>
            Saya menyadari dan mengerti bahwa pada tindakan medis, berbagai
            resiko dan komplikasi yang tidak didiskusikan sebelumnya mungkin
            dapat timbul. Saya juga menyadari bahwa selama berlangsungnya
            tindakan-tindakan perluasan operasi yang berhubungan dengan operasi
            yang dilakukan, untuk itu saya menyetujui dilakukannya tindakan
            tersebut apabila diperlukan. Selanjutnya saya menyadari bahwa tidak
            ada jaminan atau janji-janji yang diberikan kepada saya sehubungan
            dengan hasil dari segala tindakan dan atau perawatan.
          </p>
          <p>
            Bila pasien dibawah 21 tahun atau tidak dapat memberikan persetujuan
            karena alasan lain (*) tidak dapat menanda tangani surat diatas,
            pihak RS dapat mengambil kebijakan dengan memperoleh tanda tangan
            dari {result?.dari}.
          </p>
          <p>
            🧿 Membenarkan bahwa saya memilii hak untuk menandatangni
            persetujuan tindakan ini atas nama pasien tersebut.
            <br />
            🧿 Telah membaca, memahami dan menerima semua informasi pada lembar
            persetujuan ini.
            <br />
            🧿 Memastikan bahwa saya telah diberi penjelasan dan mengerti dengan
            baik tentang tindakan tersebut.
          </p>
        </div>

        <p className='text-right text-xs mb-4'>
          Pematangsiantar, {result?.tanggal ?? ''}
        </p>

        {/* Tanda Tangan 2x2 */}
        <div className='border border-black'>
          <div className='flex border-b border-black'>
            <TandaTanganBox
              title='Dokter Anastesi'
              nama={result?.dokter_anastesi}
            />
            <TandaTanganBox
              title='Disetujui oleh pasien'
              nama={result?.disetujuan_oleh_pasien}
            />
          </div>
          <div className='flex'>
            <TandaTanganBox
              title='Pihak Rumah Sakit'
              nama={result?.pihak_rumah_sakit}
            />
            <TandaTanganBox
              title='Pihak Keluarga Pasien'
              nama={result?.pihak_keluarga_pasien}
            />
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

function TandaTanganBox({ title, nama }: { title: string; nama?: string }) {
  return (
    <div className='flex-1 flex flex-col items-center gap-1 p-3 text-center text-xs'>
      <p className='font-semibold'>{title}</p>
      <QRCode value={nama ?? '-'} className='h-[80px] w-[80px]' />
      <p>( {nama ?? ''} )</p>
    </div>
  )
}
