import type { Response, Triase } from '@/type'

// import { get } from './api'
import { get as get3 } from './api-3'



const getTriase = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<Triase>> => {
  const response = await get3(`/v1/report-triase/${noreg}`)

  return response.data
}

const getTriasePonek = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<Triase>> => {
  const response = await get3(`/v1/report-triase-ponek/${noreg}`)

  return response.data
}

export { getTriase, getTriasePonek }
