import type {  Response } from '@/type'

import {  post } from '../../../services/api'


const getKartuObservasi = async ({
    noreg,
}: {
    noreg: string
}): Promise<Response<Kartuobservasi[]>> => {
    const response = await post(`/v1/kartu-observasi/get`, {
    "no_reg" : noreg
})

    return response.data
}

export { getKartuObservasi}



export interface Kartuobservasi {
    id_observasi:  number;
    jam:           string;
    t:             string;
    n:             string;
    p:             string;
    s:             string;
    cvp:           string;
    ekg:           string;
    pupil_kiri:    string;
    pupil_kanan:   string;
    redaksi_kiri:  string;
    redaksi_kanan: string;
    anggota_badan: string;
    kesadaran:     string;
    sputum_warna:  string;
    isi_cup:       string;
    keterangan:    string;
}
