import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { getPengkajianKeperawatanDewasaDiIGD } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportPengkajianKeperawatanDewasaDiIGDProps {
  isReport?: boolean
  no?: string
  noreg?: string
  no_rm?: string
}

function RowInfo({ title, value }: { title: string; value?: string }) {
  return (
    <div className='flex border-b border-black last:border-b-0'>
      <div className='w-[190px] shrink-0 p-1 text-[9px] font-semibold border-r border-black'>
        {title}
      </div>
      <div className='flex-1 p-1 text-[9px]'>{value ?? ''}</div>
    </div>
  )
}

function SectionTitle({ children }: { children: React.ReactNode }) {
  return (
    <p className='font-semibold text-[10px] my-2 border-y border-black py-0.5 px-1 bg-gray-100'>
      {children}
    </p>
  )
}

export function ReportPengkajianKeperawatanDewasaDiIGD({
  isReport = false,
  no = '',
  noreg = '',
}: ReportPengkajianKeperawatanDewasaDiIGDProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.asesmenKeperawatanDewasaDiIGD,
      noreg,
    ],
    queryFn: () =>
      getPengkajianKeperawatanDewasaDiIGD({
        no_reg: noreg,
        usia: 'DEWASA',
      }),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null

  if (isError) return <Error />
  if (result == null)
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
      </LayoutBorderNo>
    )

  const a = result.persistem
  const b = result.pengkajian
  const v = result.vital_sign
  const r = result.resiko_jatuh

  const resikoJatuhLevel =
    r?.total != null ? (r.total >= 12 ? 'Risiko Tinggi' : 'Risiko Rendah') : ''
  const resikoJatuhAdvice =
    r?.total != null
      ? r.total >= 12
        ? 'Pasang gelang risiko jatuh berwarna kuning'
        : 'Tidak perlu gelang risiko jatuh'
      : ''

  // const v = result.vital

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PENGKAJIAN AWAL PASIEN DEWASA DI IGD
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        <SectionTitle>
          II. PENGKAJIAN AWAL KEPERAWATAN (di isi oleh perawat)
        </SectionTitle>

        <div className='border border-black'>
          <RowInfo
            title='Tanggal / Jam'
            value={`${formatTanggalV3(b.insert_dttm ?? '')} / ${b.insert_dttm?.substring(11, 19) ?? ''} WIB`}
          />
          <RowInfo title='Cara Masuk' value={b.cara_masuk ?? ''} />
          <RowInfo title='Asal Pasien' value={b.asal_masuk ?? ''} />
          <RowInfo
            title='Keluhan Utama/Alasan Masuk RS'
            value={b.keluhan_utama ?? ''}
          />
          <RowInfo
            title='Riwayat Penyakit Sekarang'
            value={b.riwayat_penyakit_sekarang ?? ''}
          />

          <RowInfo
            title='Riwayat Penyakit Dahulu'
            value={b.riwayat_penyakit_dahulu ?? ''}
          />
          <RowInfo
            title='Riwayat Penyakit Keluarga'
            value={b.riwayat_penhyakit_keluarga ?? ''}
          />
        </div>

        <SectionTitle>Riwayat Pengobatan Dirumah</SectionTitle>
        <div className='border border-black mb-2'>
          <div className='flex bg-gray-100'>
            <SimpleColumn
              head
              name='Nama Obat'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Dosis'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Cara Pemberian'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Frekuensi'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Waktu Terakhir'
              isLast
              className='p-1 flex-1'
              className2='text-[9px]'
            />
          </div>
          {result.pengobatan_dirumah?.map((p, i) => (
            <div key={i} className='flex'>
              <SimpleColumn
                name={p.nama_obat}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={p.dosis}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={p.cara_pemberian}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={p.frekuensi}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                isLast
                name={p.waktu}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
          ))}
          {result.pengobatan_dirumah?.length == 0 && (
            <p className='text-center text-[9px] p-1'>-</p>
          )}
        </div>

        <SectionTitle>Riwayat Alergi</SectionTitle>
        <div className='border border-black mb-2'>
          <RowInfo title='Riwayat Alergi' value={b.riwayat_alergi ?? ''} />
          <RowInfo title='Reaksi yang timbul' value={b.reaksi_alergi ?? ''} />
        </div>

        <SectionTitle>Pengkajian Persistem</SectionTitle>

        <div className='border border-black'>
          <RowInfo title='AIR WAYS' value={a?.airways} />

          <RowInfo title='BREATHING' value={a?.breathing} />

          <RowInfo title='CIRCULATION' value={a?.circulation} />

          <RowInfo title='DISABILITY/NEUROLOGIS' value={a?.disability} />

          <RowInfo title='SISTEM PERKEMIHAN' value={a?.sistem_perkemihan} />

          <RowInfo title='SISTEM PENCERNAAN' value={a?.sistem_pencernaan} />

          <RowInfo
            title='SISTEM INTEGUMEN/MUSCHULOSKLETAL'
            value={a?.sistem_integumen}
          />

          <RowInfo
            title='SISTEM KEBIDANAN/KANDUNGAN'
            value={a?.sistem_kebidanan}
          />

          <RowInfo title='THT/MATA' value={a?.sistem_tht} />

          <RowInfo title='METABOLISME' value={a?.sistem_metabolisme} />

          <RowInfo title='PSIKIATRI/PSIKOLOGIS' value={a?.sistem_psikologis} />

          <RowInfo
            title='SISTEM SOSIO KULTURAL'
            value={a?.sistem_sosio_kultural}
          />
        </div>

        <div className='mt-4'>
          <SectionTitle>Pengkajian Nyeri</SectionTitle>
          <RowInfo
            title='Apakah Ada Nyeri / Tidak Nyaman ?'
            value={b.nyeri ?? ''}
          />

          <div className='border border-black mb-2'>
            <div className='flex bg-gray-100'>
              <SimpleColumn
                head
                name='PENYEBAB'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='KUALITAS'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='PENYEBARAN'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='KEPERAHAN'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='WAKTU'
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />

              <SimpleColumn
                head
                name='LOKASI'
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
            <div className='flex'>
              <SimpleColumn
                name={result?.nyeri?.penyebab}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={result?.nyeri?.kualitas}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={result?.nyeri?.penyebaran}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={result?.nyeri?.keparahan}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                isLast
                name={result?.nyeri?.waktu}
                className='p-1 flex-1'
                className2='text-[9px]'
              />

              <SimpleColumn
                isLast
                name={result?.nyeri?.lokasi}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
          </div>
        </div>

        <div className='mt-4'>
          <SectionTitle>Pengkajian Resiko Jatuh</SectionTitle>
          <div className='border border-black'>
            <RowInfo title='Riwayat Jatuh' value={r?.riwayat_jatuh} />
            <RowInfo title='Diagnosis' value={r?.diagnosis} />
            <RowInfo title='Alat Bantu Jalan' value={r?.alat_bantu_jalan} />
            <RowInfo title='Menggunakan Infus' value={r?.menggunakan_infuse} />
            <RowInfo title='Cara Berjalan' value={r?.cara_berjalan} />
            <RowInfo title='Status Mental' value={r?.status_mental} />
            <RowInfo title='Total Skor' value={r?.total?.toString()} />
          </div>

          <div className='border border-black mt-2 bg-red-600 text-white p-2 text-[10px] font-semibold'>
            <div>{`TINGKAT RISIKO : ${resikoJatuhLevel}`}</div>
            <div>{resikoJatuhAdvice}</div>
          </div>
        </div>

        <div className='mt-4'>
          <SectionTitle>Pengkajian Nutrisi</SectionTitle>

          <div className='border border-black'>
            <div className='flex bg-gray-100'>
              <SimpleColumn
                head
                name='PARAMETER'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='NILAI'
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
            <div className='flex'>
              <SimpleColumn
                name='Apakah pasien mengalami penurunan BB yang tidak diinginkan dalam 6 bulan terakhir ?'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                isLast
                name={result.nutrisi?.n1}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
            <div className='flex'>
              <SimpleColumn
                name='Apakah asupan makanan berkurang karena tidak nafsu makan ?'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                isLast
                name={result.nutrisi?.n2}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
            <div className='flex'>
              <SimpleColumn
                name='TOTAL'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                isLast
                name={`${result.nutrisi?.nilai ?? ''}`}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>

            <div className='border border-black mt-2 bg-yellow-100 text-black p-2 text-[10px] font-semibold'>
              <div>{`Bila Skor >=2 Konsultasi Ke Ahli Gizi`}</div>
            </div>
          </div>
        </div>

        <div className='mt-4'>
          <SectionTitle>Diagnosa Keperawatan</SectionTitle>
          {result.asuhan_keperawatan?.map((item, i) => (
            <div
              key={item.no_daskep ?? i}
              className='border border-black mb-2 p-1'
            >
              <p className='text-[10px] font-semibold'>
                {item.diagnosa?.judul?.toUpperCase()} ( {item.diagnosa?.kode} )
              </p>
              <p className='text-[9px]'>
                Tanggal : {formatTanggalV3(item.tanggal) ?? item.tanggal}
              </p>
              {item.deskripsi_slki?.map((s, j) => (
                <p key={j} className='text-[9px]'>
                  ◉ {s.nama_sllki}
                </p>
              ))}
            </div>
          ))}
          {result.asuhan_keperawatan?.length == 0 && (
            <p className='text-center text-[9px] p-2'>Tidak ada data</p>
          )}
        </div>

        <SectionTitle>Evaluasi Keperawatan</SectionTitle>
        <div className='border border-black'>
          <div className='flex bg-gray-100'>
            <SimpleColumn
              name='No.'
              className='w-[25px]'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='EVALUASI (SOAP/SBAR)'
              isLast
              className='p-1 flex-1'
              className2='text-[9px]'
            />
          </div>

          <div className='flex'>
            <SimpleColumn
              name='1'
              className='w-[25px]'
              className2='text-[9px]'
            />
            <SimpleColumn
              isLast
              name={'-'}
              className='p-1 flex-1'
              className2='text-[9px]'
            />
          </div>
        </div>

        <SectionTitle>Kondisi Pasien Saat Meninggalkan IGD</SectionTitle>
        <p className='text-left text-[9px]'>RAWAT INAP {b.tindak_lanjut}</p>
        <p className='text-left text-[9px]'>Indikasi {b.indikasi}</p>
        <p className='text-left text-[9px]'>Ruangan {b.ruangan}</p>
        <p className='text-left text-[9px]'>DPJP {b.dpjp}</p>

        <br />
        <SectionTitle>Pendidikan Kesahatan Saat Pasien Pulang</SectionTitle>
        <p className='text-left text-[9px]'>
          Discard Planning {b.discharge_planning}
        </p>

        <br />
        <SectionTitle>Observasi Pasien Saat Meninggalkan IGD</SectionTitle>
        <p className='text-left text-[9px]'>
          Discard Planning {b.discharge_planning}
        </p>

        <RowInfo
          title='Vital Sign'
          value={`TD ${v?.td ?? ''} / RR ${v?.pernafasan ?? ''} / Nadi ${v?.nadi ?? ''} / Temp ${v?.suhu ?? ''} / BB ${v?.berat_badan ?? ''} / TB ${v?.tinggi_badan ?? ''} / SpO2 ${v?.spo2 ?? ''}`}
        />
      </div>

      <br />
      <SectionTitle>
        Pasien dan keluarga telah menjelaskan dan mengerti sepenuhnya diagnosa,
        kondisi, rencana pengobatan dan prognosa penyakit pasien terkini :
      </SectionTitle>

      {/* Signature */}
      <div className='flex items-start justify-around mt-6 p-2'>
        <div className='flex flex-col items-center gap-1 text-center text-xs'>
          <p>Perawat</p>
          <QRCode
            value={result?.perawat.nama ?? '-'}
            className='h-[60px] w-[60px]'
          />
          <p>( {result?.perawat.nama} )</p>
        </div>
        <div className='flex flex-col items-center gap-1 text-center text-xs'>
          <p>Diketahui: Pasien/Keluarga Pasien</p>
          <QRCode
            value={result?.perawat.nama ?? '-'}
            className='h-[60px] w-[60px]'
          />
          <p>( {pasien?.nama_pasien} )</p>
        </div>

        <div className='flex flex-col items-center gap-1 text-center text-xs'>
          <p>Dokter yang memeriksa</p>
          <QRCode
            value={result?.pengkajian.dpjp ?? '-'}
            className='h-[60px] w-[60px]'
          />
          <p>( {result?.pengkajian.dpjp} )</p>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
