import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { getPemberianInformasi } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextField } from './text-field'

interface ReportPemberianInformasiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportPemberianInformasi({
  isReport = false,
  no = '',
  noreg = '',
}: ReportPemberianInformasiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemberianInformasi, noreg],
    queryFn: () => getPemberianInformasi(noreg),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const info = result?.informasi_tindakan

  const checklist = [
    {
      title: 'Diagnosa',
      value: info?.diagnosa,
      active: info?.is_active_diagnosa,
    },
    {
      title: 'Dasar Diagnosa',
      value: info?.dasar_diagnosa,
      active: info?.is_active_dasar_diagnosa,
    },
    {
      title: 'Tindakan Kedokteran',
      value: info?.tindakan_kedokteran,
      active: info?.is_active_tindakan_kedokteran,
    },
    {
      title: 'Indikasi Tindakan',
      value: info?.indikasi_tindakan,
      active: info?.is_active_indikasi_tindakan,
    },
    {
      title: 'Tata Cara',
      value: info?.tata_cara,
      active: info?.is_active_tata_cara,
    },
    { title: 'Tujuan', value: info?.tujuan, active: info?.is_active_tujuan },
    { title: 'Resiko', value: info?.resiko, active: info?.is_active_resiko },
    {
      title: 'Komplikasi',
      value: info?.komplikasi,
      active: info?.is_active_komplikasi,
    },
    {
      title: 'Prognosa',
      value: info?.prognosa,
      active: info?.is_active_prognosa,
    },
    {
      title: 'Alternatif dan Resiko',
      value: info?.alternatif_dan_resiko,
      active: info?.is_active_alternatif_dan_resiko,
    },
    {
      title: 'Lain-lain',
      value: info?.lain_lain,
      active: info?.is_active_lain_lain,
    },
  ]

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PEMBERIAN INFORMASI
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        <div className='p-2 border border-black space-y-2.5 mb-4'>
          <TextField
            title='Pemberi Informasi'
            value={result?.pemberi_informasi}
          />
          <TextField
            title='Pelaksanaan Tindakan'
            value={result?.pelaksana_tindakan}
          />
          <TextField
            title='Penerima Informasi/Pemberi Persetujuan'
            value={result?.penerima_informasi}
          />
        </div>

        <div className='p-2 border border-black mb-4'>
          <h2 className='text-center text-black font-semibold mb-2'>
            INFORMASI TINDAKAN KEDOKTERAN
          </h2>
          <div className='flex'>
            <SimpleColumn
              head
              name='NO'
              className='w-[30px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='CEKLIS'
              className='w-[50px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='DESKRIPSI'
              isLast
              className='p-1 flex-1'
              className2='text-[10px]'
            />
          </div>
          {checklist.map((item, i) => (
            <div key={i} className='flex'>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[30px] p-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.active ? '✓' : '✗'}
                className='w-[50px] p-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                isLast
                isChild={
                  <div className='text-[10px] text-left'>
                    <span className='font-semibold'>{item.title}: </span>
                    <span>{item.value}</span>
                  </div>
                }
                className='p-1 flex-1'
              />
            </div>
          ))}
        </div>

        {/* Tanda Tangan */}
        <div className='flex items-start justify-around p-2'>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>Pemberi Informasi</p>
            {result?.ttd_pemberi_informasi ? (
              <img
                alt='ttd'
                src={`${import.meta.env.VITE_BASE_API_URL}/app/images/pemberian_informasi/${result?.ttd_pemberi_informasi}`}
                className='h-[80px] w-[80px]'
              />
            ) : (
              <QRCode
                value={result?.nama_pemberi_informasi ?? '-'}
                className='h-[80px] w-[80px]'
              />
            )}
            <p>( {result?.nama_pemberi_informasi ?? ''} )</p>
          </div>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>Penerima Informasi</p>
            {result?.ttd_penerima_informasi ? (
              <img
                alt='ttd'
                src={`${import.meta.env.VITE_BASE_API_URL}/app/images/pemberian_informasi/${result?.ttd_penerima_informasi}`}
                className='h-[80px] w-[80px]'
              />
            ) : (
              <QRCode
                value={result?.nama_penerima_informasi ?? '-'}
                className='h-[80px] w-[80px]'
              />
            )}
            <p>( {result?.nama_penerima_informasi ?? ''} )</p>
          </div>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>Saksi</p>
            {result?.ttd_saksi ? (
              <img
                alt='ttd'
                src={`${import.meta.env.VITE_BASE_API_URL}/app/images/pemberian_informasi/${result?.ttd_saksi}`}
                className='h-[80px] w-[80px]'
              />
            ) : (
              <QRCode
                value={result?.nama_saksi ?? '-'}
                className='h-[80px] w-[80px]'
              />
            )}
            <p>( {result?.nama_saksi ?? ''} )</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
