import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'
import clsx from 'clsx'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { formatTanggalV2, formatTanggalV3 } from '@/helper/date'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { FieldValueBox } from '../component/field_value'
import { GcsBadge } from '../component/gcs_badge'
import SignatureBlock from '../component/signature'
import {
  KriteriaMasukIntensive,
  LaborMasuk,
  NilaiLabor,
  Prioritas,
  RadiologiMasuk,
  getAllKriteriaMasuk,
} from './masuk'

interface KriteriaPasienMasukPasienProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function KriteriaPasienMasukPasien({
  isReport = false,
  noreg = '',
  no = '',
}: KriteriaPasienMasukPasienProps) {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.kriteriaPasienMasukICU, noreg],
    queryFn: () => getAllKriteriaMasuk({ noreg }),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  const selected = result[index]

  const Selected = ({ data }: { data: KriteriaMasukIntensive }) => {
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <h1 className='text-center text-black font-semibold mb-2'>
            KRITERIA PASIEN MASUK RAWAT INTENSIF
          </h1>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien ?? ''}
              noRM={pasien?.no_rm ?? ''}
              ruangan={pasien.bagian ?? ''}
              tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
              jk={pasien.jenis_kelamin ?? ''}
            />
          )}
          {/* Informasi Pasien */}
        </div>

        {/* ===== Identitas ===== */}
        <div className='grid grid-cols-1 divide-y divide-slate-300 border-b border-slate-300 sm:grid-cols-[160px_1fr] sm:divide-x sm:divide-y-0'>
          <div className='bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-700'>
            Asal Ruangan
          </div>
          <div className='flex flex-wrap gap-2 px-4 py-3'>
            {RUANGAN_LIST.map((r) => {
              const active = r === data.asal_ruangan
              return (
                <span
                  key={r}
                  className={`rounded-sm px-3 py-1.5 text-sm font-medium ${
                    active
                      ? 'bg-emerald-500 text-white'
                      : 'bg-slate-200 text-slate-600'
                  }`}
                >
                  {r}
                </span>
              )
            })}
          </div>
        </div>
        <div className='grid grid-cols-1 divide-y divide-slate-300 border-b border-slate-300 sm:grid-cols-[160px_1fr] sm:divide-x sm:divide-y-0'>
          <div className='bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-700'>
            Dokter DPJP
          </div>
          <div className='flex items-center px-4 py-3 text-sm text-slate-800'>
            {data.dokter_dpjp?.nama || '-'}
          </div>
        </div>
        <div className='grid grid-cols-1 divide-y divide-slate-300 border-b border-slate-300 sm:grid-cols-[160px_1fr] sm:divide-x sm:divide-y-0'>
          <div className='bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-700'>
            Tanggal / Jam
          </div>
          <div className='flex items-center px-4 py-3 text-sm text-slate-800'>
            {data.tanggal} {data.jam ? `— ${data.jam}` : ''}
          </div>
        </div>

        {/* ===== Kriteria Pasien Masuk Intensif ===== */}
        <div className='px-6 pt-6'>
          <SectionLabel>Kriteria Pasien Masuk Intensif</SectionLabel>
        </div>
        <div className='mx-6 mb-6 overflow-hidden rounded-sm border border-slate-300'>
          <div className='grid grid-cols-[56px_160px_1fr] border-b border-slate-300 bg-slate-100 text-sm font-semibold text-slate-700'>
            <div className='border-r border-slate-300 px-2 py-2'>No.</div>
            <div className='border-r border-slate-300 px-2 py-2'>Prioritas</div>
            <div className='px-3 py-2'>Kriteria</div>
          </div>
          <PrioritasBlock no={1} label='Prioritas 1' items={data.prioritas1} />
          <PrioritasBlock no={2} label='Prioritas 2' items={data.prioritas2} />
          <PrioritasBlock no={3} label='Prioritas 3' items={data.prioritas3} />
        </div>

        {/* ===== EWS ===== */}
        <div className='px-6'>
          <SectionLabel>EWS (Early Warning System)</SectionLabel>
        </div>
        <div className='mx-6 mb-6 space-y-4'>
          <div className='flex flex-wrap items-center gap-6 rounded-sm border border-slate-300 bg-white px-4 py-3'>
            <span className='text-sm font-semibold text-slate-700'>GCS</span>
            <GcsBadge label='E' value={data.vital_sign.gcs_e} />
            <GcsBadge label='V' value={data.vital_sign.gcs_v} />
            <GcsBadge label='M' value={data.vital_sign.gcs_m} />
          </div>

          <div className='flex items-center gap-3 rounded-sm border border-slate-300 bg-white px-4 py-3'>
            <span className='text-sm font-semibold text-slate-700'>
              Kesadaran
            </span>
            <span className='rounded bg-blue-600 px-3 py-1 text-sm font-semibold text-white'>
              {data.vital_sign.kesadaran || '-'}
            </span>
          </div>

          <div>
            <div className='mb-2 text-sm font-semibold text-slate-700'>
              Tanda-Tanda Vital
            </div>
            <div className='grid grid-cols-1 gap-3 rounded-sm border border-slate-300 bg-white p-4 sm:grid-cols-2'>
              <VitalRow label='TD' value={data.vital_sign.td} unit='mmHg' />
              <VitalRow label='HR' value={data.vital_sign.hr} unit='x/mnt' />
              <VitalRow label='RR' value={data.vital_sign.rr} unit='x/mnt' />
              <VitalRow label='Temp' value={data.vital_sign.temp} unit='°C' />
              <VitalRow label='Spo2' value={data.vital_sign.spo2} unit='%' />
            </div>
          </div>

          {/* Pemeriksaan Penunjang */}
          <div>
            <div className='mb-2 text-sm font-semibold text-slate-700'>
              Pemeriksaan Penunjang
            </div>
            <div className='space-y-3'>
              {data.labor_masuk.map((l, idx) => (
                <LaborTable key={idx} labor={l} />
              ))}
              <NilaiLaborGrid nilai={data.nilai_labor} />
            </div>
          </div>

          {/* Fisioterapi / EKG / Radiologi */}
          <div>
            <div className='mb-2 text-sm font-semibold text-slate-700'>
              Fisioterapi / Electrocardiogram / Radiologi
            </div>
            <div className='space-y-3'>
              {data.radiologi_masuk.map((r, idx) => (
                <RadiologiEkgTable key={idx} item={r} />
              ))}
              {data.radiologi ? (
                <div className='rounded-sm border border-slate-300 bg-white px-3 py-2 text-sm'>
                  <span className='font-semibold text-slate-700'>
                    Radiologi:{' '}
                  </span>
                  <span className='text-slate-800'>{data.radiologi}</span>
                </div>
              ) : null}
              {data.fisio.length === 0 && (
                <p className='text-xs text-slate-300'>
                  Belum ada catatan fisioterapi.
                </p>
              )}
            </div>
          </div>
        </div>

        {/* ===== Diagnosa ===== */}
        <div className='px-6'>
          <SectionLabel>Diagnosa</SectionLabel>
        </div>
        <div className='mx-6 mb-6 overflow-hidden rounded-sm border border-slate-300'>
          <table className='w-full text-left text-sm'>
            <thead>
              <tr className='bg-slate-100 text-slate-700'>
                <th className='px-3 py-2 font-semibold'>No.</th>
                <th className='px-3 py-2 font-semibold'>Kode</th>
                <th className='px-3 py-2 font-semibold'>Deskripsi</th>
                <th className='px-3 py-2 font-semibold'>Diagnosa</th>
              </tr>
            </thead>
            <tbody>
              {data.diagnosa_masuk.length > 0 ? (
                data.diagnosa_masuk.map((d, idx) => (
                  <tr key={idx} className='border-t border-slate-200'>
                    <td className='px-3 py-2 text-slate-600'>{idx + 1}</td>
                    <td className='px-3 py-2 font-medium text-slate-800'>
                      {d.code || '-'}
                    </td>
                    <td className='px-3 py-2 text-slate-800'>
                      {d.description || '-'}
                    </td>
                    <td className='px-3 py-2 text-slate-800'>
                      {d.diagnosa || '-'}
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td
                    colSpan={4}
                    className='px-3 py-4 text-center text-sm text-slate-300'
                  >
                    Belum ada diagnosa
                  </td>
                </tr>
              )}
            </tbody>
          </table>
          {data.diagnosis ? (
            <div className='border-t border-slate-300 px-3 py-2 text-sm text-slate-800'>
              {data.diagnosis}
            </div>
          ) : null}
        </div>

        {/* ===== Tindak Lanjut ===== */}
        <div className='px-6'>
          <SectionLabel>Tindak Lanjut</SectionLabel>
        </div>
        <div className='mx-6 mb-6 rounded-sm border border-slate-300 bg-white px-4 py-3 text-sm text-slate-800'>
          <p>{data.tindak_lanjut || '-'}</p>
          {data.tindak_lanjut_detail ? (
            <p className='mt-1 text-slate-600'>{data.tindak_lanjut_detail}</p>
          ) : null}
        </div>

        {/* ===== Tanda Tangan ===== */}
        <div className='flex flex-col gap-4 px-6 pb-6 sm:flex-row'>
          <SignatureBlock title='Dokter DPJP' dokter={data.dokter_dpjp} />
          <SignatureBlock
            title='Dokter Penanggung Jawab Intensif'
            dokter={data.dokter_penanggung_jawab}
          />
        </div>

        {/* Content */}
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {result.length > 0 &&
        result.map((item, idx) => (
          <Button
            className={clsx(index == idx && 'bg-green-500 text-white m-4')}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {formatTanggalV2(item.tanggal)}
          </Button>
        ))}

      {selected != null ? <Selected data={selected} /> : null}
    </>
  )
}

/* ==================== Small building blocks ==================== */

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <h2 className='border-b-2 border-slate-800 pb-1 mb-3 text-[15px] font-bold uppercase tracking-wide text-slate-900'>
      {children}
    </h2>
  )
}

function PrioritasRow({ item }: { item: Prioritas }) {
  return (
    <div
      className={`flex items-center gap-2.5 rounded-sm border px-3 py-2 text-sm ${
        item.is_active
          ? 'border-emerald-300 bg-emerald-50 font-semibold text-emerald-900'
          : 'border-slate-200 bg-white text-slate-700'
      }`}
    >
      <span
        className={`flex h-4 w-4 flex-none items-center justify-center rounded-sm text-[11px] ${
          item.is_active ? 'bg-emerald-500 text-white' : 'text-slate-300'
        }`}
      >
        {item.is_active ? '✓' : '–'}
      </span>
      <span>{item.title}</span>
    </div>
  )
}

function PrioritasBlock({
  no,
  label,
  items,
}: {
  no: number
  label: string
  items: Prioritas[]
}) {
  return (
    <div className='grid grid-cols-[56px_160px_1fr] border-b border-slate-300 last:border-b-0'>
      <div className='border-r border-slate-300 px-2 py-3 text-sm text-slate-700'>
        {no}.
      </div>
      <div className='border-r border-slate-300 px-2 py-3 text-sm font-semibold text-slate-800'>
        {label}
      </div>
      <div className='flex flex-col gap-1.5 px-3 py-3'>
        {items.map((it, idx) => (
          <PrioritasRow key={idx} item={it} />
        ))}
      </div>
    </div>
  )
}

function VitalRow({
  label,
  value,
  unit,
}: {
  label: string
  value: string
  unit?: string
}) {
  return (
    <div className='grid grid-cols-[70px_1fr] items-center gap-3'>
      <span className='text-sm font-medium text-slate-600'>{label}</span>
      <FieldValueBox>
        {value ? (
          <span>
            {value}
            {unit ? <span className='ml-1 text-slate-400'>{unit}</span> : null}
          </span>
        ) : null}
      </FieldValueBox>
    </div>
  )
}

function LaborTable({ labor }: { labor: LaborMasuk }) {
  return (
    <div className='overflow-hidden rounded-sm border border-slate-300'>
      <div className='flex flex-wrap items-center justify-between gap-2 bg-slate-100 px-3 py-2 text-sm'>
        <span className='font-semibold text-slate-800'>
          {labor.nama_kelompok}
        </span>
        <span className='text-slate-500'>
          {labor.tanggal}
          {labor.jaminput ? ` · Input ${labor.jaminput}` : ''}
          {labor.jamselesai ? ` – Selesai ${labor.jamselesai}` : ''}
          {labor.lama ? ` (${labor.lama})` : ''}
        </span>
      </div>
      {labor.penlab.length > 0 ? (
        <table className='w-full text-left text-sm'>
          <thead>
            <tr className='bg-slate-50 text-slate-600'>
              <th className='border-t border-slate-300 px-3 py-2 font-medium'>
                Pemeriksaan
              </th>
              <th className='border-t border-slate-300 px-3 py-2 font-medium'>
                Hasil
              </th>
              <th className='border-t border-slate-300 px-3 py-2 font-medium'>
                Satuan
              </th>
              <th className='border-t border-slate-300 px-3 py-2 font-medium'>
                Nilai Normal
              </th>
              <th className='border-t border-slate-300 px-3 py-2 font-medium'>
                Kategori
              </th>
            </tr>
          </thead>
          <tbody>
            {labor.penlab.map((p, idx) => (
              <tr key={idx} className='border-t border-slate-200'>
                <td className='px-3 py-2 text-slate-800'>
                  {p.pemeriksaan_deskripsi}
                </td>
                <td
                  className={`px-3 py-2 font-semibold ${
                    p.kategori?.toLowerCase() === 'abnormal'
                      ? 'text-red-600'
                      : 'text-slate-800'
                  }`}
                >
                  {p.hasil}
                </td>
                <td className='px-3 py-2 text-slate-500'>{p.satuan}</td>
                <td className='px-3 py-2 text-slate-500'>{p.normal}</td>
                <td className='px-3 py-2 text-slate-500'>{p.kategori}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div className='px-3 py-4 text-sm text-slate-300'>
          Belum ada hasil laboratorium
        </div>
      )}
    </div>
  )
}

function NilaiLaborGrid({ nilai }: { nilai: NilaiLabor }) {
  const rows: { label: string; key: keyof NilaiLabor; unit?: string }[] = [
    { label: 'Glukosa', key: 'glukosa', unit: 'mg/dL' },
    { label: 'Ureum', key: 'ureum', unit: 'mg/dL' },
    { label: 'Creatinin', key: 'creatinin', unit: 'mg/dL' },
    { label: 'Natrium', key: 'natrium', unit: 'mmol/L' },
    { label: 'Kalium', key: 'kalium', unit: 'mmol/L' },
    { label: 'pH Darah', key: 'ph_darah' },
    { label: 'PaO2', key: 'pa_o2', unit: 'mmHg' },
    { label: 'PCO2', key: 'pc_o2', unit: 'mmHg' },
    { label: 'Lain-lain', key: 'lain_lain' },
  ]
  const hasAny = rows.some((r) => nilai[r.key])
  if (!hasAny) return null
  return (
    <div className='grid grid-cols-2 gap-x-6 gap-y-2 rounded-sm border border-slate-300 bg-white p-3 sm:grid-cols-3'>
      {rows.map((r) => (
        <div
          key={r.key}
          className='flex items-baseline justify-between gap-2 text-sm'
        >
          <span className='text-slate-500'>{r.label}</span>
          <span className='font-semibold text-slate-800'>
            {nilai[r.key] || '-'}
            {nilai[r.key] && r.unit ? (
              <span className='ml-1 font-normal text-slate-400'>{r.unit}</span>
            ) : null}
          </span>
        </div>
      ))}
    </div>
  )
}

function RadiologiEkgTable({ item }: { item: RadiologiMasuk }) {
  const tanggal =
    item.tanggal instanceof Date
      ? item.tanggal.toLocaleDateString('id-ID')
      : item.tanggal
  return (
    <div className='overflow-hidden rounded-sm border border-slate-300'>
      <div className='bg-slate-100 px-3 py-2 text-sm font-semibold text-slate-800'>
        {item.nama_kelompok} {tanggal ? `— Tanggal: ${tanggal}` : ''}
      </div>
      {item.radiologi.map((r, idx) => (
        <div
          key={idx}
          className='grid grid-cols-1 divide-y divide-slate-200 border-t border-slate-300 sm:grid-cols-3 sm:divide-x sm:divide-y-0'
        >
          <div className='px-3 py-2'>
            <div className='text-xs font-medium uppercase text-slate-400'>
              Pemeriksaan
            </div>
            <div className='text-sm text-slate-800'>
              {r.pemeriksaan_deskripsi || '-'}
            </div>
          </div>
          <div className='px-3 py-2'>
            <div className='text-xs font-medium uppercase text-slate-400'>
              Uraian
            </div>
            <div className='text-sm text-slate-800'>{r.uraian || '-'}</div>
          </div>
          <div className='px-3 py-2'>
            <div className='text-xs font-medium uppercase text-slate-400'>
              Hasil
            </div>
            <div className='text-sm text-slate-800'>{r.hasil || '-'}</div>
          </div>
        </div>
      ))}
    </div>
  )
}

const RUANGAN_LIST = [
  'Martina',
  'Martina 2',
  'Maria',
  'Lukas',
  'ICU',
  'Isolasi',
  'Libreks',
  'Meinalda',
  'Perinatologi',
  'Kamar Operasi',
  'IGD',
]
