import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'
import clsx from 'clsx'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { Button } from '@/components/ui/button'
import { formatTanggalV3 } from '@/helper/date'
import type {
  ReasesmenResikoJatuhDewasa,
  ReasesmenResikoJatuhFaktor,
} from '@/models/reasesmen-resiko-jatuh-dewasa'
import { getReasesmenResikoJatuhDewasa } from '@/services/daftar-obat-harian'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReasesmenResikoJatuhDewasaProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

const FAKTOR_KEYS: {
  key: keyof ReasesmenResikoJatuhDewasa
}[] = [
  { key: 'riwayat_jatuh' },
  { key: 'status_mental' },
  { key: 'medikasi' },
  { key: 'mobilisasi' },
  { key: 'alat_bantu' },
  { key: 'diagnosis' },
  { key: 'terapi_intravena' },
]

export function ReasesmenResikoJatuhDewasa({
  isReport = false,
  noreg = '',
  no = '',
}: ReasesmenResikoJatuhDewasaProps) {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.reasesmenResikoJatuhDewasa, noreg],
    queryFn: () => getReasesmenResikoJatuhDewasa({ noreg }),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  const selected = result[index]

  const skorFaktor = (faktor: ReasesmenResikoJatuhFaktor) =>
    faktor.kriteria
      .filter((k) => k.is_active)
      .reduce((acc, k) => acc + k.skor, 0)

  const Selected = ({ data }: { data: ReasesmenResikoJatuhDewasa }) => {
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <h1 className='text-center text-black font-semibold mb-2'>
            REASESMEN PASIEN RESIKO JATUH PADA DEWASA
          </h1>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien ?? ''}
              noRM={pasien?.no_rm ?? ''}
              ruangan={pasien.bagian ?? ''}
              tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
              jk={pasien.jenis_kelamin ?? ''}
            />
          )}
          {/* Informasi Pasien */}
        </div>

        <div className='p-2'>
          <p className='text-xs mb-1'>
            Tanggal : {formatTanggalV3(data.tanggal)}
          </p>

          <div className='flex'>
            <SimpleColumn
              head
              name='No.'
              className='w-[50px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='Faktor Resiko'
              className='p-1 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name=''
              className='p-1 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='Skor'
              className='w-[100px] p-1'
              className2='text-[10px]'
              isLast
            />
          </div>

          {FAKTOR_KEYS.map(({ key }, idx) => {
            const faktor = data[key] as ReasesmenResikoJatuhFaktor

            return (
              <div key={key} className='flex'>
                <div className='flex flex-1'>
                  <SimpleColumn
                    name={`${idx + 1}`}
                    className='w-[50px] p-1 border-t-0'
                    className2='text-[10px]'
                  />
                  <SimpleColumn
                    name={faktor.title}
                    className='p-1 border-t-0 flex-1'
                    className2='text-[10px]'
                  />
                  <SimpleColumn
                    name=''
                    className='p-1 border-t-0 flex-1'
                    className2='text-[10px]'
                    isChild={
                      <div className='h-full w-full text-start'>
                        {faktor.kriteria.map((kriteria, i) => (
                          <div
                            key={i}
                            className={clsx(
                              'flex items-start justify-between mb-2 p-1 border-b border-black',
                              kriteria.is_active && 'bg-green-500 text-white'
                            )}
                          >
                            <p className='text-[10px]'>{kriteria.title}</p>
                            <p className='text-[10px]'>{kriteria.skor}</p>
                          </div>
                        ))}
                      </div>
                    }
                  />
                  <SimpleColumn
                    name={skorFaktor(faktor).toString()}
                    className='p-1 border-t-0 w-[100px]'
                    className2='text-[10px]'
                    isLast
                  />
                </div>
              </div>
            )
          })}

          <div className='flex flex-1'>
            <SimpleColumn
              name=''
              className='w-[50px] p-1 border-t-0'
              className2='text-[10px]'
            />
            <SimpleColumn
              name='Total Skor'
              className='p-1 border-t-0 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              name=''
              className='p-1 border-t-0 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              name={data.total.toString()}
              className='p-1 border-t-0 w-[100px]'
              className2='text-[10px]'
              isLast
            />
          </div>

          <p className='text-xs mt-2'>
            Lakukan pengkajian (skoring risiko jatuh pada saat pasien masuk
            ketika terjadi perubahan kondisi pasien/terapi, saat pindah ruangan
            lain, pasien risiko tinggi dikaji setiap 24 jam atau sesaat setelah
            terjadi kasus jatuh) <br />
            Skor :{' '}
            <div>
              0 - 24 Resiko Rendah (RR) <br />
              {'>'} 25 - 44 Resiko Sedang (RS)
              <br /> {'>='} 45 Resiko Tinggi (RT){' '}
            </div>
          </p>
        </div>

        <div className='flex flex-col gap-4 items-center text-center text-xs mt-[100px]'>
          {data.perawat != '' && (
            <>
              <p className='text-sm'>
                Pematangsiantar {formatTanggalV3(data.tanggal)} <br />
                Perawat
              </p>
              <QRCode
                value={data.perawat ?? '-'}
                className='w-[100px] h-[100px]'
              />
              <p className=''>( {data.perawat ?? '-'} )</p>
            </>
          )}
        </div>

        {/* Content */}
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {result.length > 0 &&
        result.map((item, idx) => (
          <Button
            className={clsx(index == idx && 'bg-green-500 text-white')}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {formatTanggalV3(item.tanggal)}
          </Button>
        ))}

      {selected != null ? <Selected data={selected} /> : null}
    </>
  )
}
