import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { getRegisterPasien } from '@/services/general-consent'
import { getPengkajianKeperawatanDewasa } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportPengkajianKeperawatanDewasaProps {
  isReport?: boolean
  no?: string
  noreg?: string
  no_rm?: string
}

function RowInfo({ title, value }: { title: string; value?: string }) {
  return (
    <div className='flex border-b border-black last:border-b-0'>
      <div className='w-[190px] shrink-0 p-1 text-[9px] font-semibold border-r border-black'>
        {title}
      </div>
      <div className='flex-1 p-1 text-[9px]'>{value ?? ''}</div>
    </div>
  )
}

function SectionTitle({ children }: { children: React.ReactNode }) {
  return (
    <p className='font-semibold text-[10px] my-2 border-y border-black py-0.5 px-1 bg-gray-100'>
      {children}
    </p>
  )
}

const FUNGSIONAL_ITEMS: { key: string; label: string }[] = [
  { key: 'f1', label: 'Makan' },
  { key: 'f2', label: 'Aktivitas di toilet' },
  { key: 'f3', label: 'Berpindah' },
  { key: 'f4', label: 'Kebersihan diri' },
  { key: 'f5', label: 'Mandi' },
  { key: 'f6', label: 'Berjalan' },
  { key: 'f7', label: 'Naik turun tangga' },
  { key: 'f8', label: 'Berpakaian' },
  { key: 'f9', label: 'Mengontrol defekasi' },
  { key: 'f10', label: 'Mengontrol berkemih' },
]

export function ReportPengkajianKeperawatanDewasa({
  isReport = false,
  no = '',
  no_rm = '',
  noreg = '',
}: ReportPengkajianKeperawatanDewasaProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data: registerData, isLoading: isRegisterLoading } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.listRegisterPasien, no_rm],
    queryFn: () => getRegisterPasien({ no_rm }),
    enabled: no_rm != '',
  })

  const kdBagian =
    registerData?.response.find((item) => item.noreg == noreg)?.kd_bagian ?? ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.pengkajianKeperawatanDewasa,
      noreg,
      kdBagian,
    ],
    queryFn: () =>
      getPengkajianKeperawatanDewasa({
        no_reg: noreg,
        no_rm,
        kd_bagian: kdBagian,
      }),
    enabled: noreg != '' && kdBagian != '',
  })

  const result = data != null ? data.response : null

  if (isRegisterLoading || isLoading) return <Loading />
  if (isError) return <Error />
  if (result == null || result.asesmen == null)
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
      </LayoutBorderNo>
    )

  const a = result.asesmen
  const f = result.fisik
  const v = result.vital

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PENGKAJIAN AWAL PASIEN DEWASA RAWAT INAP
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        <SectionTitle>
          II. PENGKAJIAN AWAL KEPERAWATAN (di isi oleh perawat)
        </SectionTitle>

        <div className='border border-black'>
          <RowInfo
            title='Tanggal / Jam'
            value={`${formatTanggalV3(a.tgl_masuk ?? '')} / ${a.insert_dttm?.substring(11, 19) ?? ''}`}
          />
          <RowInfo title='Jenis Pengkajian' value={a.jenpel ?? ''} />
          <RowInfo
            title='Jenis Pengkajian Detail'
            value={a.jenpel_detail ?? ''}
          />
          <RowInfo
            title='Keluhan Utama/Alasan Masuk RS'
            value={a.keluhan ?? ''}
          />
          <RowInfo
            title='Riwayat Penyakit Sekarang'
            value={a.riwayat_penyakit ?? ''}
          />
        </div>

        <SectionTitle>Riwayat Penyakit Dahulu</SectionTitle>
        <div className='border border-black'>
          {result.riwayat_penyakit_dahulu?.map((r, i) => (
            <RowInfo
              key={i}
              title={`Tanggal: ${r.tgl_masuk ?? ''}`}
              value={r.keluh_utama ?? ''}
            />
          ))}
          {result.riwayat_penyakit_dahulu?.length == 0 && (
            <RowInfo title='-' value='' />
          )}
        </div>

        <SectionTitle>Riwayat Penyakit Keluarga</SectionTitle>
        <div className='border border-black'>
          {result.riwayat_keluarga?.map((r, i) => (
            <RowInfo
              key={i}
              title={`Tanggal: ${r.tanggal ?? ''}`}
              value={r.penyakit ?? ''}
            />
          ))}
          {result.riwayat_keluarga?.length == 0 && (
            <RowInfo title='-' value='' />
          )}
        </div>

        <SectionTitle>Riwayat Pengobatan Dirumah</SectionTitle>
        <div className='border border-black mb-2'>
          <div className='flex bg-gray-100'>
            <SimpleColumn
              head
              name='Nama Obat'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Dosis'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Cara Pemberian'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Frekuensi'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Waktu Terakhir'
              isLast
              className='p-1 flex-1'
              className2='text-[9px]'
            />
          </div>
          {result.pengobatan?.map((p, i) => (
            <div key={i} className='flex'>
              <SimpleColumn
                name={p.nama_obat}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={p.dosis}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={p.cara_pemberian}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={p.frekuensi}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                isLast
                name={p.waktu}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
          ))}
          {result.pengobatan?.length == 0 && (
            <p className='text-center text-[9px] p-1'>-</p>
          )}
        </div>

        <SectionTitle>Riwayat Alergi</SectionTitle>
        <div className='border border-black mb-2'>
          <RowInfo title='Reaksi yang timbul' value={a.reaksi_alergi ?? ''} />
        </div>

        <SectionTitle>Pengkajian Fisik</SectionTitle>
        <div className='border border-black mb-2'>
          <RowInfo
            title='Vital Sign'
            value={`TD ${v?.td ?? ''} / RR ${v?.pernafasan ?? ''} / Nadi ${v?.nadi ?? ''} / Temp ${v?.suhu ?? ''} / BB ${v?.berat_badan ?? ''} / TB ${v?.tinggi_badan ?? ''} / SpO2 ${v?.spo2 ?? ''}`}
          />
          <RowInfo
            title='GCS'
            value={`E${f?.gcs_e ?? ''} V${f?.gcs_v ?? ''} M${f?.gcs_m ?? ''}`}
          />
        </div>

        {/* PENGKAJIAN | MASALAH KEPERAWATAN */}
        <div className='flex gap-2'>
          {/* LEFT */}
          <div className='flex-1'>
            <SectionTitle>PENGKAJIAN</SectionTitle>

            <SectionTitle>PEMERIKSAAN FISIK</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='KEPALA' value={f?.kepala} />
              <RowInfo title='MATA' value={f?.mata} />
              <RowInfo title='TELINGA' value={f?.telinga} />
              <RowInfo title='LEHER DAN BAHU' value={f?.lehe} />
              <RowInfo title='HIDUNG' value={f?.hidung} />
              <RowInfo title='GIGI' value={f?.gigi} />
              <RowInfo title='DADA' value={f?.dada} />
              <RowInfo title='ABDOMEN' value={f?.abdomen} />
            </div>

            <SectionTitle>NUTRISI DAN HIDRASI</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='NUTRISI' value={a.nutrisi ?? ''} />
            </div>

            <SectionTitle>
              PENGKAJIAN NUTRISI (Malnutrion Screening Tool)
            </SectionTitle>
            <div className='border border-black'>
              <div className='flex bg-gray-100'>
                <SimpleColumn
                  head
                  name='PARAMETER'
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  head
                  name='NILAI'
                  isLast
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              </div>
              <div className='flex'>
                <SimpleColumn
                  name='N1'
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  isLast
                  name={result.nutrisi?.n1}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              </div>
              <div className='flex'>
                <SimpleColumn
                  name='N2'
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  isLast
                  name={result.nutrisi?.n2}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              </div>
              <div className='flex'>
                <SimpleColumn
                  name='TOTAL'
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  isLast
                  name={`${result.nutrisi?.nilai ?? ''}`}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              </div>
            </div>

            <SectionTitle>ELIMINASI DAN PELEPASAN</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='ELIMINASI BAK' value={a.eliminasi_bak ?? ''} />
              <RowInfo title='ELIMINASI BAB' value={a.eliminasi_bab ?? ''} />
            </div>

            <SectionTitle>AKTIVITAS / ISTIRAHAT</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='TIDUR/ISTIRAHAT' value={a.istirahat ?? ''} />
            </div>

            <SectionTitle>SKOR AKTIVITAS</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='MANDI' value={a.sistem_mandi ?? ''} />
              <RowInfo title='BERPAKAIAN' value={a.sistem_berpakaian ?? ''} />
              <RowInfo title='MAKAN/MANDI' value={a.sistem_makan ?? ''} />
              <RowInfo title='ELIMINASI' value={a.sistem_eliminasi ?? ''} />
              <RowInfo
                title='MOBILISASI DI TT'
                value={a.sistem_mobilisasi ?? ''}
              />
            </div>

            <SectionTitle>SISTEM KARDIO-RESPIRATORI</SectionTitle>
            <div className='border border-black'>
              <RowInfo
                title='KARDIOVASKULER'
                value={a.sistem_kardiovaskuler ?? ''}
              />
              <RowInfo title='AKRAL' value={a.akral ?? ''} />
              <RowInfo title='RESPIRATORI' value={a.sistem_respiratori ?? ''} />
              <RowInfo title='BATUK' value={a.batuk ?? ''} />
              <RowInfo title='SUARA NAPAS' value={a.suara_napas ?? ''} />
              <RowInfo title='MEROKOK' value={a.merokok ?? ''} />
            </div>

            <SectionTitle>SISTEM PERFUSI SECEBRAL</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='SECEBRAL' value={a.sistem_secebral ?? ''} />
              <RowInfo title='SAKIT KEPALA' value={a.sakit_kepala ?? ''} />
              <RowInfo
                title='PERUBAHAN STATUS MENTAL'
                value={a.perubahan_status_mental ?? ''}
              />
              <RowInfo
                title='LEMAH ANGGOTA GERAK'
                value={a.anggota_gerak ?? ''}
              />
              <RowInfo title='BICARA' value={a.bicara ?? ''} />
              <RowInfo
                title='RIWAYAT HIPERTENSI'
                value={a.riwayat_hipertensi ?? ''}
              />
              <RowInfo title='PUPIL' value={f?.pupil} />
            </div>

            <SectionTitle>THERMOREGULASI</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='THERMOREGULASI' value={a.thermoregulasi ?? ''} />
            </div>

            <SectionTitle>SISTEM PERFUSI PERIFER</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='SECEBRAL' value={a.sistem_secebral ?? ''} />
            </div>

            <SectionTitle>SISTEM PENCERNAAN</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='PENCERNAAN' value={a.sistem_pencernaan ?? ''} />
              <RowInfo title='BISING USUS' value={a.sistem_usus ?? ''} />
            </div>

            <SectionTitle>INTEGUMEN</SectionTitle>
            <div className='border border-black'>
              <RowInfo title='INTEGUMEN' value={a.sistem_integumen ?? ''} />
            </div>

            <SectionTitle>PENGKAJIAN FUNGSIONAL</SectionTitle>
            <div className='border border-black'>
              <div className='flex bg-gray-100'>
                <SimpleColumn
                  head
                  name='KRITERIA BARTHEL INDEX'
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  head
                  name='HASIL'
                  isLast
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              </div>
              {FUNGSIONAL_ITEMS.map((item) => (
                <div key={item.key} className='flex'>
                  <SimpleColumn
                    name={item.label}
                    className='p-1 flex-1'
                    className2='text-[9px]'
                  />
                  <SimpleColumn
                    isLast
                    name={`${result.fungsional?.[item.key as keyof typeof result.fungsional] ?? ''}`}
                    className='p-1 flex-1'
                    className2='text-[9px]'
                  />
                </div>
              ))}
              <div className='flex'>
                <SimpleColumn
                  name='TOTAL'
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  isLast
                  name={`${result.fungsional?.nilai ?? ''}`}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
              </div>
            </div>

            <SectionTitle>KOMUNIKASI/PENDIDIKAN/PENGAJARAN</SectionTitle>
            <div className='border border-black'>
              <RowInfo
                title='Hambatan Bahasa'
                value={a.hambatan_bahasa ?? ''}
              />
              <RowInfo
                title='Cara belajar yang disukai'
                value={a.cara_belajar ?? ''}
              />
              <RowInfo
                title='Bahasa Sehari hari'
                value={a.bahasa_sehari ?? ''}
              />
              <RowInfo
                title='Perlu penerjemah'
                value={a.perlu_penerjemah ?? ''}
              />
            </div>

            <SectionTitle>
              DATA SPIKOLOGIS, SOSIAL, EKONOMI DAN SPIRITUAL
            </SectionTitle>
            <div className='border border-black'>
              <RowInfo title='Spikologis' value={a.spikologis ?? ''} />
              <RowInfo
                title='Hambatan Sosial'
                value={a.hambatan_sosial ?? ''}
              />
              <RowInfo
                title='Hambatan Ekonomi'
                value={a.hambatan_ekonomi ?? ''}
              />
              <RowInfo
                title='Hambatan Spiritual'
                value={a.hambatan_spiritual ?? ''}
              />
              <RowInfo title='Response Emosi' value={a.response_emosi ?? ''} />
            </div>

            <SectionTitle>NILAI KEPERCAYAAN</SectionTitle>
            <div className='border border-black'>
              <RowInfo
                title='MENJALANKAN IBADAH'
                value={a.nilai_kepercayaan ?? ''}
              />
              <RowInfo
                title='PRESEPSI TERHADAP SAKIT'
                value={a.presepsi_sakit ?? ''}
              />
              <RowInfo
                title='KUNJUNGAN PEMIMPIN AGAMA/SPIRITUAL'
                value={a.hambatan_spiritual ?? ''}
              />
              <RowInfo
                title='NILAI/ATURAN KHUSUS DALAM KEPERCAYAAN'
                value={a.khusus_kepercayaan ?? ''}
              />
            </div>
          </div>

          {/* RIGHT */}
          <div className='flex-1'>
            <SectionTitle>MASALAH KEPERAWATAN</SectionTitle>
            {result.asuhan?.map((item, i) => (
              <div
                key={item.no_daskep ?? i}
                className='border border-black mb-2 p-1'
              >
                <p className='text-[10px] font-semibold'>
                  {item.diagnosa?.judul?.toUpperCase()} ( {item.diagnosa?.kode}{' '}
                  )
                </p>
                <p className='text-[9px]'>
                  Tanggal : {formatTanggalV3(item.tanggal) ?? item.tanggal}
                </p>
                {item.deskripsi_slki?.map((s, j) => (
                  <p key={j} className='text-[9px]'>
                    ◉ {s.nama_sllki}
                  </p>
                ))}
              </div>
            ))}
            {result.asuhan?.length == 0 && (
              <p className='text-center text-[9px] p-2'>Tidak ada data</p>
            )}
          </div>
        </div>

        {/* Signature */}
        <div className='flex items-start justify-around mt-6 p-2'>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>KARU/KATIM</p>
            <p className='h-[60px]' />
            <p>( ................. )</p>
          </div>
          <div className='flex flex-col items-center gap-1 text-center text-xs'>
            <p>PERAWAT YANG BERTUGAS</p>
            <QRCode value={a.nama ?? '-'} className='h-[60px] w-[60px]' />
            <p>( {a.nama ?? ''} )</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
