import type { AsesmenDokterRanap, Response } from '@/type'

import { get,  } from './api-3'
import { AsesmenMedisIGD } from '@/features/pasien/asesmen-medis-rawat-igd/medis-igd'

const getAsesmenDokterRanap = async ({
    noreg,
}: {
    noreg: string
}): Promise<Response<AsesmenDokterRanap>> => {
    const response = await get(`/v1/asesmen-dokter-rawat-inap/${noreg}`)

    return response.data
}


const getAsesmenDokterIGD = async ({
    noreg,
    norm
}: {
    noreg: string
    norm : string
}): Promise<Response<AsesmenMedisIGD>> => {
    const response = await get(`/v1/asesmen-dokter-igd/${noreg}`,
         { no_reg: noreg, no_rm :norm}
    )
    return response.data
}

export { getAsesmenDokterRanap, getAsesmenDokterIGD }
