import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'
import clsx from 'clsx'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import Text from '@/components/text'
import { Button } from '@/components/ui/button'
import { formatTanggalV3 } from '@/helper/date'
import { TransferPasienModel } from '@/models/transfer-pasien'
import { getAllTransferPasien } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { Labor } from '@/type'
import { constants } from '@/utils/constants'

import { DiagnosaTable } from './diagnosa-table'
import { LaborTable } from './labor-table'
import { TeruskanObatTable } from './teruskan-obat-table'

interface ReportTransferPasienProps {
  isReport?: boolean
  noreg?: string

  no?: string
}

export function ReportTransferPasien({
  isReport = false,
  noreg = '',

  no = '',
}: ReportTransferPasienProps) {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.transferPasien, noreg],
    queryFn: () => getAllTransferPasien({ noreg }),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  const dpjp = result[index]?.data.dokter_yang_merawat.find(
    (d) => d.dokter == 'dpjp'
  )?.nama_dokter

  const Selected = ({ data }: { data: TransferPasienModel }) => {
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <h1 className='text-center text-black font-semibold mb-2'>
            CATATAN TRANSFER PASIEN ANTAR RUANGAN
          </h1>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien ?? ''}
              noRM={pasien?.no_rm ?? ''}
              ruangan={pasien.bagian ?? ''}
              tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
              jk={pasien.jenis_kelamin ?? ''}
            />
          )}
          {/* Informasi Pasien */}

          <div className='px-2'>
            <SectionHeader title='SITUATION' />
            <div className='text-xs text-black flex items-center justify-between'>
              <p>Pemindahan pasien : {data.data.tanggal_transfer}</p>
              <p>Pukul : {data.data.jam_transfer} WIB</p>
            </div>
            <div className='my-2'>
              <Text k='Dari' v={data.data.dari} />
              <Text k='Ke' v={data.data.ke} />
              {data.data.dokter_yang_merawat.length > 0 &&
                data.data.dokter_yang_merawat.map((d, i) => (
                  <Text key={i} k='Dokter yang Merawat' v={d.nama_dokter} />
                ))}
              <Text k='Diagnosa Medis' v='' />
              <div className='mb-2' />
              {data.data.diagnosa.length > 0 && (
                <DiagnosaTable data={data.data.diagnosa} />
              )}
              <Text
                k='Pasien / Keluarga sudah dijelaskan mengenai diagnosis'
                v={data.data.penjelasan_diagnosis}
              />
              <Text
                k='Prosedur pembedahan / invasive yang dilakukan'
                v={data.data.prosedur_pembedahan}
              />
              <Text k='Masalah keperawatan utama saat ini' v='' />
              {data.data.masalah_keperawatan.length > 0 &&
                data.data.masalah_keperawatan.map((m, i) => (
                  <div key={i} className='text-xs mb-1'>
                    <p className='text-black font-semibold'>
                      {' '}
                      {i + 1}.{m.judul}
                    </p>
                    <p className='text-xs text-black ml-4'>
                      {m.nama_slki_list}
                    </p>
                  </div>
                ))}
            </div>
            <SectionHeader title='BACKGROUND' />
            <Text
              k='Riwayat Alergi / Reaksi Obat'
              v={data.data.riwayat_alergi}
            />
            <Text k='Riwayat Reaksi' v={data.data.riwayat_reaksi_alergi} />
            <Text
              k='Intervensi Medic / Keperawatan'
              v={data.data.intervensi_keperawatan}
            />
            <Text
              k='Hasil Investigasi Abnormal'
              v={data.data.hasil_intervensi}
            />
            <Text k='Kewaspadaan / Precaution' v={data.data.kewaspadaan} />
            <SectionHeader title='ASESMENT' />
            <div className='flex gap-4 justify-between items-start'>
              <div>
                <Text
                  k='Observasi Terakhir Pukul'
                  v={data.data.pemfisik.observasi}
                />
                <Text
                  k='Tingkat Kesadaran'
                  v={data.data.pemfisik.tingkat_kesadaran}
                />
                <Text k='GCS E' v={data.data.pemfisik.gcs_e} />
                <Text k='GCS V' v={data.data.pemfisik.gcs_v} />
                <Text k='GCS M' v={data.data.pemfisik.gcs_m} />
                <Text k='Pupil Kiri' v={data.data.pemfisik.pupil_kiri} />
                <Text k='Pupil Kanan' v={data.data.pemfisik.pupil_kanan} />
                <Text k='TD' v={data.data.pemfisik.td + ' mmHg'} />
                <Text k='Nadi' v={data.data.pemfisik.nadi + ' x/menit'} />
                <Text
                  k='Respirasi'
                  v={data.data.pemfisik.respirasi + ' x/menit'}
                />
                <Text k='Spo2' v={data.data.pemfisik.spo2 + ' %'} />
                <Text k='Suhu' v={data.data.pemfisik.suhu + ' °C'} />
                <Text k='Skala Nyeri' v={data.data.pemfisik.skala_nyeri} />
                <Text k='Diet / Nutrisi' v={data.data.pemfisik.diet_nutrisi} />
                <Text k='Diet Khusus' v={data.data.pemfisik.diet_khusus} />
                <Text k='BAB' v={data.data.pemfisik.bab} />
                <Text k='Jenis' v={data.data.pemfisik.jenis} />
                {/* </div>
              <div> */}
                <Text k='No' v={data.data.pemfisik.nomor} />
                <Text
                  k='Tanggal Pemasangan'
                  v={data.data.pemfisik.tanggal_pemasangan}
                />
                <Text k='BAK' v={data.data.pemfisik.bak} />
                <Text k='Mobilisasi' v={data.data.pemfisik.mobilisasi} />
                <Text
                  k='Transfer / Mobilisasi'
                  v={data.data.pemfisik.transfer_mobilisasi}
                />
                <Text
                  k='Alat bantu yang digunakan'
                  v={data.data.pemfisik.alat_bantu_yang_digunakan}
                />
                <Text k='Luka' v={data.data.pemfisik.luka} />
                <Text k='Jenis Luka' v={data.data.pemfisik.jenis_luka} />
                <Text k='Kondisi' v={data.data.pemfisik.kondisi} />
                <Text k='Luas Luka' v={data.data.pemfisik.luas_luka} />
                <Text k='Infus' v={data.data.pemfisik.infus} />
                <Text k='Lokasi Infus' v={data.data.pemfisik.lokasi_infus} />
                <Text
                  k='Tanggal Pemasangan Infus'
                  v={data.data.pemfisik.tgl_pemasangan_infus}
                />
                <Text
                  k='Tindakan / Kebutuhan Khusus'
                  v={data.data.pemfisik.kebutuhan_khusus}
                />
                <Text k='Peralatan khusus yang diperlukan' v='' />
                <Text
                  k='Hal - hal istimewa yang berhubungan dengan kondisi pasien sebelum / selama transfer'
                  v={data.data.pemfisik.khusus_yang_diperlukan}
                />
                <Text
                  k='Diagnosa Keperawatan'
                  v={data.data.masalah_keperawatan
                    .map((item) => item.judul)
                    .join(', ')}
                />
              </div>
            </div>
            <SectionHeader title='RECOMMENDATION' />
            <Text k='Konsultasi' v={data.data.recomendation.konsultasi} />
            <Text
              k='Rencana Pemeriksaan Penunjang'
              v={data.data.rencana_desc}
            />
            <Text k='Rencana Terapi' v={data.data.terapy_desc} />
            <Text
              k='Fisioterapi'
              v={data.data.recomendation.fisioteraphy_mobilisasi}
            />
            <Text
              k='Persiapan Pulang'
              v={data.data.recomendation.persiapan_pulang}
            />
            <Text
              k='Rencana Tindak Lanjut'
              v={data.data.recomendation.rencana_tindak_lajut}
            />
            <Text k='Rekonsiliasi Obat Saat Pasien Transfer' v='' />
            {data.data.teruskan_obat.length > 0 && (
              <TeruskanObatTable data={data.data.teruskan_obat} />
            )}
            <div className='flex items-center justify-between'>
              <Text
                k='Apoteker yang merekonsilias obat'
                v={data.data.recomendation.apoteker}
              />
              <Text
                k='Tanggal/Pukul'
                v={data.data.recomendation.tanggal_merekonsilasi}
              />
            </div>
            <Text k='Catatan dan barang dokumen disertakan' />
            <div className='flex items-start gap-4'>
              <div className='flex-1'>
                <LaborTable data={data.data.labor as Labor[]} />
              </div>
              <div>
                <Text k='Barang Pasien' v={data.data.barang_pasien} />
                <Text k='Barang Rumah Sakit' v={data.data.barang_rumah_sakit} />
              </div>
            </div>
            <Text k='Lain-lain' v={data.data['lain-lain']} />
          </div>

          <div className='mt-[100px] p-2 mb-1 m-2 flex items-center justify-between'>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {data.data != null && data.data.ttd_dokter_dpjp == '' ? (
                <>
                  <p className='text-sm'>DPJP</p>
                  <QRCode value={dpjp ?? '-'} className='w-[100px] h-[100px]' />
                  <p className=''>({dpjp ?? '-'})</p>
                </>
              ) : (
                <>
                  <p className='text-sm'>DPJP</p>
                  <img
                    alt='ttd'
                    src={`${import.meta.env.VITE_BASE_API_URL}/app/images/catatan_transfer/${data.data.ttd_dokter_dpjp}`}
                    className='w-[100px] h-[100px]'
                  />
                  <p className=''>({dpjp ?? '-'})</p>
                </>
              )}
            </div>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {data.data != null && data.data.ttd_yang_menyerahkan == '' ? (
                <>
                  <p className='text-sm'>Yang Menyerahkan</p>
                  <QRCode
                    value={data.data.nama_yang_menyerahkan ?? '-'}
                    className='w-[100px] h-[100px]'
                  />
                  <p className=''>({data.data.nama_yang_menyerahkan ?? '-'})</p>
                </>
              ) : (
                <>
                  <p className='text-sm'>Yang Menyerahkan</p>
                  <img
                    alt='ttd'
                    src={`${import.meta.env.VITE_BASE_API_URL}/app/images/catatan_transfer/${data.data.ttd_yang_menyerahkan}`}
                    className='w-[100px] h-[100px]'
                  />
                  <p className=''>({data.data.nama_yang_menyerahkan ?? '-'})</p>
                </>
              )}
            </div>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {data.data != null && data.data.ttd_yang_menerima == '' ? (
                <>
                  <p className='text-sm'>Yang Menerima</p>
                  <QRCode
                    value={data.data.nama_yang_menerima ?? '-'}
                    className='w-[100px] h-[100px]'
                  />
                  <p className=''>({data.data.nama_yang_menerima ?? '-'})</p>
                </>
              ) : (
                <>
                  <p className='text-sm'>Yang Menerima</p>

                  <img
                    alt='ttd'
                    src={`${import.meta.env.VITE_BASE_API_URL}/app/images/catatan_transfer/${data.data.ttd_yang_menerima}`}
                    className='w-[100px] h-[100px]'
                  />
                  <p className=''>({data.data.nama_yang_menerima ?? '-'})</p>
                </>
              )}
            </div>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {data.data != null && data.data.ttd_yang_mengetahui == '' ? (
                <>
                  <p className='text-sm'>Mengetahui</p>
                  <QRCode
                    value={data.data.nama_yang_mengetahui ?? '-'}
                    className='w-[100px] h-[100px]'
                  />
                  <p className=''>({data.data.nama_yang_mengetahui ?? '-'})</p>
                </>
              ) : (
                <>
                  <p className='text-sm'>Mengetahui</p>
                  <img
                    alt='ttd'
                    src={`${import.meta.env.VITE_BASE_API_URL}/app/images/catatan_transfer/${data.data.ttd_yang_mengetahui}`}
                    className='w-[100px] h-[100px]'
                  />
                  <p className=''>({data.data.nama_yang_mengetahui ?? '-'})</p>
                </>
              )}
            </div>
          </div>
        </div>

        {/* Content */}
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {result.length > 0 &&
        result.map((item, idx) => (
          <Button
            className={clsx(index == idx && 'bg-green-500 text-white')}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {item.ruangan}
          </Button>
        ))}

      {result.length > 0 ? <Selected data={result[index]} /> : null}
    </>
  )
}

const SectionHeader = ({ title }: { title: string }) => {
  return (
    <div className='flex justify-center items-center bg-black text-white p-2 my-2'>
      <h3>{title}</h3>
    </div>
  )
}
