import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasienBox } from '@/components/informasi_pasien_box'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { SimpleTTD } from '@/components/simple-ttd'
import {
  formatJam,
  formatTanggalIndonesia,
  formatTanggalJam,
} from '@/helper/date'
import { DaftarObat } from '@/models/pemberian_obat'
import { getDaftarObat } from '@/services/daftar-obat-harian'
import { constants } from '@/utils/constants'

interface DaftarObatProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function DaftarObatHarian({
  isReport = true,
  noreg = '',
}: DaftarObatProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.daftarObat, noreg],
    queryFn: () => getDaftarObat({ no_reg: noreg }),
  })

  const result = data?.response != null ? data?.response : ({} as DaftarObat)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          DAFTAR OBAT HARIAN
        </h1>

        {result?.profil_pasien && (
          <InformasiPasienBox
            nama={result.profil_pasien.nama}
            noRM={result.profil_pasien.no_rm}
            jenisKelamin={result.profil_pasien.jenis_kelamin}
            tanggalLahir={result.profil_pasien.tgl_lahir}
          />
        )}

        <div>
          {/* Header */}
          <div className='flex text-xs'>
            <SimpleColumn head name='No.' className='w-[50px]' />
            <SimpleColumn head name='Tanggal & Jam' className='flex-1' />
            <SimpleColumn
              head
              name='Obat Injeksi Dan Dosis'
              className='w-[200px]'
            />
            <SimpleColumn head name='Jam Diberi' className='flex-1' />
            <SimpleColumn head name='Frekuensi' className='w-[80px]' />
            <SimpleColumn head name='Jam Diberi' className='flex-1' />
            <SimpleColumn head name='Cara Pemberian' className='flex-1' />
            <SimpleColumn head name='Sisa Obat' className='flex-1' />
            <SimpleColumn head name='Perawatan' className='flex-1' />
            <SimpleColumn
              head
              name='Pasien/Keluarga'
              className='w-[200px] border border-black text-center'
            />
          </div>
        </div>

        {result?.obat?.length > 0 ? (
          result.obat.map((item, index) => (
            <div className='flex text-xs' key={item.id}>
              <div className='flex text-xs' key={item.id}>
                <SimpleColumn
                  name={(index + 1).toString()}
                  className='w-[50px]'
                />
                <SimpleColumn
                  name={formatTanggalIndonesia(item.insert_dttm)}
                  className='flex-1 '
                />
                <SimpleColumn name={item.nama_obat} className='w-[200px]' />
                <SimpleColumn
                  name={formatJam(item.jam_diberi)}
                  className='flex-1'
                />
                <SimpleColumn
                  name={item.frekuensi.toString()}
                  className='w-[80px] '
                />
                <SimpleColumn
                  name={formatTanggalJam(item.jam_diberi)}
                  className='flex-1'
                />
                <SimpleColumn name={item.cara_pemberian} className='flex-1 ' />
                <SimpleColumn name={item.sisa_obat} className='flex-1 ' />
                <SimpleColumn name={item.user.nama} hasQR className='flex-1' />
                <SimpleTTD
                  imageSrc={`${import.meta.env.VITE_BASE_API_URL}/app/images/instruksi_farmakologi/${item.file_tdd}`}
                  name={item.ttd_nama}
                  className='w-[200px] border'
                />
              </div>
            </div>
          ))
        ) : (
          <div className='flex justify-center items-center py-4 text-sm text-gray-500'>
            Data obat kosong
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}
