
import { Response } from '@/type'
import { EWSModel } from './ews-model'
import { post } from '@/services/api-2'

export const initEWS: EWSModel = {
  kontrol_pasien: [],
  keterangan: {
    ringan: '',
    sedang: '',
    tinggi: '',
    henti_nafas: '',
  },
  monitoring_cairan: [],
  nyeri: [],
}

const getEws = async ({
  noReg,
  kdBagian,
}: {
  kdBagian: string
  noReg: string
}): Promise<Response<EWSModel>> => {
  const response = await post(`/v1/data-kontrol-pasien`, {
    kd_bagian: kdBagian,
    no_reg: noReg,
  })

  return response.data
}

const getEwsAnak = async ({
  noReg,
  noRM,
}: {
  noRM: string
  noReg: string
}): Promise<Response<EWSModel>> => {
  const response = await post(`/v1/data-kontrol-pasien`, {
    no_reg: noReg,
    kategori : "ANAK",
    no_rm : noRM
  })

  return response.data
}

