import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { ResikoJatuhMorse } from '@/models/resiko-jatuh-morse'
// import QRCode from 'react-qr-code'
import { getReportResikoJatuhDewasa } from '@/services/daftar-obat-harian'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import TableResikoJatuhMorse from './table-resiko-jatuh-morse'

// import { Edit } from 'lucide-react'

interface ReportResikoJatuhMorseProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportResikoJatuhMorse({
  isReport = false,
  noreg = '',
  no = '',
}: ReportResikoJatuhMorseProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.resikojatuh, noreg],
    queryFn: () =>
      getReportResikoJatuhDewasa({
        no_reg: noreg,
        kd_bagian: pasien?.kd_bagian ?? '',
      }),
  })

  const result =
    data?.response != null ? data?.response : ({} as ResikoJatuhMorse)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          ASESMEN PASIEN RESIKO JATUH PADA DEWASA
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}
        {/* Informasi Pasien */}
      </div>

      <div className='p-2'>
        <TableResikoJatuhMorse data={result} />
        <p className='text-xs'>
          Lakukan pengkajian (skoring risiko jatuh pada saat pasien masuk ketika
          terjadi perubahan kondisi pasien/terapi, saat pindah ruangan lain,
          pasien risiko tinggi dikaji setiap 24 jam atau sesaat setelah terjadi
          kasus jatuh) <br />
          Skor :{' '}
          <div>
            0 - 24 Resiko Rendah (RR) <br />
            {'>'} 25 - 44 Resiko Sedang (RS)
            <br /> {'>='} 45 Resiko Tinggi (RT){' '}
          </div>
        </p>
      </div>

      {/* Content */}
    </LayoutBorderNo>
  )
}
