import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'
import clsx from 'clsx'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { LaborTable } from '@/features/pasien-pulang/rekam-medis/components/labor-table'
import { TextTitle } from '@/features/pasien-pulang/rekam-medis/components/text-title'
import { formatTanggalV2, formatTanggalV3 } from '@/helper/date'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { FieldValueBox } from '../component/field_value'
import { GcsBadge } from '../component/gcs_badge'
import { SectionLabel } from '../component/section_label'
import SignatureBlock from '../component/signature'
import {
  KriteriaKeluarIntensive,
  Prioritas,
  getAllKriteriaKeluar,
} from './keluar'

interface KriteriaPasienKeluarPasienProps {
  isReport?: boolean
  noreg?: string

  no?: string
}

export function KriteriaPasienKeluarPasien({
  isReport = false,
  noreg = '',

  no = '',
}: KriteriaPasienKeluarPasienProps) {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.KriteriaPasienKeluarICU, noreg],
    queryFn: () => getAllKriteriaKeluar({ noreg }),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  const selected = result[index]

  const Selected = ({ data }: { data: KriteriaKeluarIntensive }) => {
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <h1 className='text-center text-black font-semibold mb-2'>
            Kriteria Pasien Keluar Rawat Intensif
          </h1>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien ?? ''}
              noRM={pasien?.no_rm ?? ''}
              ruangan={pasien.bagian ?? ''}
              tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
              jk={pasien.jenis_kelamin ?? ''}
            />
          )}
          {/* Informasi Pasien */}
        </div>

        <div className='px-6 pt-6'>
          <SectionLabel>Kriteria Pasien Keluar Intensif</SectionLabel>
        </div>
        <div className='mx-6 mb-6 overflow-hidden rounded-sm border border-slate-300'>
          <div className='grid grid-cols-[56px_160px_1fr] border-b border-slate-300 bg-slate-100 text-sm font-semibold text-slate-700'>
            <div className='border-r border-slate-300 px-2 py-2'>No.</div>
            <div className='border-r border-slate-300 px-2 py-2'>Prioritas</div>
            <div className='px-3 py-2'>Kriteria</div>
          </div>
          <PrioritasBlock no={1} label='Prioritas 1' items={data.prioritas1} />
          <PrioritasBlock no={2} label='Prioritas 2' items={data.prioritas2} />
          <PrioritasBlock no={3} label='Prioritas 3' items={data.prioritas3} />
        </div>

        {/* ===== EWS ===== */}
        <div className='px-6'>
          <SectionLabel>EWS (Early Warning System)</SectionLabel>
        </div>
        <div className='mx-6 mb-6 space-y-4'>
          <div className='flex flex-wrap items-center gap-6 rounded-sm border border-slate-300 bg-white px-4 py-3'>
            <span className='text-sm font-semibold text-slate-700'>GCS</span>
            <GcsBadge label='E' value={data.vital_sign.gcs_e} />
            <GcsBadge label='V' value={data.vital_sign.gcs_v} />
            <GcsBadge label='M' value={data.vital_sign.gcs_m} />
          </div>

          <div className='flex items-center gap-3 rounded-sm border border-slate-300 bg-white px-4 py-3'>
            <span className='text-sm font-semibold text-slate-700'>
              Kesadaran
            </span>
            <span className='rounded bg-blue-600 px-3 py-1 text-sm font-semibold text-white'>
              {data.vital_sign.kesadaran || '-'}
            </span>
          </div>

          <div>
            <div className='mb-2 text-sm font-semibold text-slate-700'>
              Tanda-Tanda Vital
            </div>
            <div className='grid grid-cols-1 gap-3 rounded-sm border border-slate-300 bg-white p-4 sm:grid-cols-2'>
              <VitalRow label='TD' value={data.vital_sign.td} unit='mmHg' />
              <VitalRow label='HR' value={data.vital_sign.hr} unit='x/mnt' />
              <VitalRow label='RR' value={data.vital_sign.rr} unit='x/mnt' />
              <VitalRow label='Temp' value={data.vital_sign.temp} unit='°C' />
              <VitalRow label='Spo2' value={data.vital_sign.spo2} unit='%' />
            </div>
          </div>

          {/* Pemeriksaan Penunjang */}
          <div className='border border-black my-2 p-2'>
            <p className='flex-1 font-semibold'>PEMERIKSAAN PENUNJANG</p>
            <div>
              <TextTitle title='Laboratorium' />
              <LaborTable data={data != null ? data.labor : []} />
            </div>
          </div>
          {/* Pemeriksaan Penunjang */}

          {/* Asesmen */}
          <div className='border border-black my-2 p-2'>
            <div className='flex items-center justify-between'>
              <TextTitle title='Diagnosa' />
            </div>
            <DiagnosaTable data={data != null ? data.diagnosa_dpjp : []} />
          </div>
          {/* Asesmen */}

          {/* Asesmen */}
          <div className='border border-black my-2 p-2'>
            <div className='flex items-center justify-between'>
              <TextTitle title='Tindak Lanjut' />
            </div>
            <TextTitle
              title={data.tindak_lanjut + ' ' + data.tindak_lanjut_detail}
            />
          </div>

          {/* ===== Tanda Tangan ===== */}
          <div className='flex flex-col gap-4 px-6 pb-6 sm:flex-row'>
            <SignatureBlock title='Dokter DPJP' dokter={data.dokter_dpjp} />
            <SignatureBlock
              title='Dokter Penanggung Jawab Intensif'
              dokter={data.dokter_penanggung_jawab}
            />
          </div>

          {/* Asesmen */}
        </div>
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {result.length > 0 &&
        result.map((item, idx) => (
          <Button
            className={clsx(index == idx && 'bg-green-500 text-white m-4')}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {formatTanggalV2(item.tanggal)}
          </Button>
        ))}

      {selected != null ? <Selected data={selected} /> : null}
    </>
  )
}

function PrioritasBlock({
  no,
  label,
  items,
}: {
  no: number
  label: string
  items: Prioritas[]
}) {
  return (
    <div className='grid grid-cols-[56px_160px_1fr] border-b border-slate-300 last:border-b-0'>
      <div className='border-r border-slate-300 px-2 py-3 text-sm text-slate-700'>
        {no}.
      </div>
      <div className='border-r border-slate-300 px-2 py-3 text-sm font-semibold text-slate-800'>
        {label}
      </div>
      <div className='flex flex-col gap-1.5 px-3 py-3'>
        {items.map((it, idx) => (
          <PrioritasRow key={idx} item={it} />
        ))}
      </div>
    </div>
  )
}

function PrioritasRow({ item }: { item: Prioritas }) {
  return (
    <div
      className={`flex items-center gap-2.5 rounded-sm border px-3 py-2 text-sm ${
        item.is_active
          ? 'border-emerald-300 bg-emerald-50 font-semibold text-emerald-900'
          : 'border-slate-200 bg-white text-slate-700'
      }`}
    >
      <span
        className={`flex h-4 w-4 flex-none items-center justify-center rounded-sm text-[11px] ${
          item.is_active ? 'bg-emerald-500 text-white' : 'text-slate-300'
        }`}
      >
        {item.is_active ? '✓' : '–'}
      </span>
      <span>{item.title}</span>
    </div>
  )
}

function VitalRow({
  label,
  value,
  unit,
}: {
  label: string
  value: string
  unit?: string
}) {
  return (
    <div className='grid grid-cols-[70px_1fr] items-center gap-3'>
      <span className='text-sm font-medium text-slate-600'>{label}</span>
      <FieldValueBox>
        {value ? (
          <span>
            {value}
            {unit ? <span className='ml-1 text-slate-400'>{unit}</span> : null}
          </span>
        ) : null}
      </FieldValueBox>
    </div>
  )
}
