import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'
import clsx from 'clsx'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { Button } from '@/components/ui/button'
import { formatTanggalV2, formatTanggalV3 } from '@/helper/date'
import { IntervensiDewasa } from '@/models/intervensi-dewasa'
import { getAllIntervensiAnakPasien } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportIntervensiAnakPasienProps {
  isReport?: boolean
  noreg?: string

  no?: string
}

export function ReportIntervensiAnak({
  isReport = false,
  noreg = '',

  no = '',
}: ReportIntervensiAnakPasienProps) {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.intervensiAnakPasien, noreg],
    queryFn: () => getAllIntervensiAnakPasien({ noreg }),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  const selected = result[index]

  const Selected = ({ data }: { data: IntervensiDewasa }) => {
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <h1 className='text-center text-black font-semibold mb-2'>
            INTERVENSI PENCEGAHAN PASIEN JATUH ANAK
          </h1>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien ?? ''}
              noRM={pasien?.no_rm ?? ''}
              ruangan={pasien.bagian ?? ''}
              tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
              jk={pasien.jenis_kelamin ?? ''}
            />
          )}
          {/* Informasi Pasien */}
        </div>

        <div className='px-2 pb-2'>
          <p className='text-xs text-black mb-1'>
            Tanggal : {formatTanggalV2(data.tanggal)}
          </p>

          <div className='flex'>
            <SimpleColumn
              head
              name='No.'
              className='w-[50px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='Intervensi'
              className='p-1 flex-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='Pagi'
              className='w-[70px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='Sore'
              className='w-[70px] p-1'
              className2='text-[10px]'
            />
            <SimpleColumn
              head
              name='Malam'
              className='w-[70px] p-1'
              className2='text-[10px]'
              isLast
            />
          </div>

          {data.intervensi.map((item, idx) => (
            <div key={idx} className='flex'>
              <SimpleColumn
                name={`${item.no ?? idx + 1}`}
                className='w-[50px] p-1 border-t-0'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.title}
                className='p-1 border-t-0 flex-1 text-start'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.pagi ? '✓' : ''}
                className='w-[70px] p-1 border-t-0'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.sore ? '✓' : ''}
                className='w-[70px] p-1 border-t-0'
                className2='text-[10px]'
              />
              <SimpleColumn
                name={item.malam ? '✓' : ''}
                className='w-[70px] p-1 border-t-0'
                className2='text-[10px]'
                isLast
              />
            </div>
          ))}

          <div className='mt-[100px] p-2 flex items-start justify-between'>
            {[
              { label: 'Perawat Pagi', nama: data.nama_perawat_pagi },
              { label: 'Perawat Sore', nama: data.nama_perawat_sore },
              { label: 'Perawat Malam', nama: data.nama_perawat_malam },
            ].map((p) => (
              <div
                key={p.label}
                className='flex flex-col gap-4 items-center text-center text-xs'
              >
                <p className='text-sm'>{p.label}</p>
                {p.nama != '' ? (
                  <>
                    <QRCode value={p.nama} className='w-[100px] h-[100px]' />
                    <p>( {p.nama} )</p>
                  </>
                ) : (
                  <p>( - )</p>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Content */}
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {result.length > 0 &&
        result.map((item, idx) => (
          <Button
            className={clsx(index == idx && 'bg-green-500 text-white m-4')}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {formatTanggalV2(item.tanggal)}
          </Button>
        ))}

      {selected != null ? <Selected data={selected} /> : null}
    </>
  )
}
