import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { cn } from '@/lib/utils'
import { getRingkasanMasuk } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextField } from './text-field'

interface ReportRingkasanMasukProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

// Daftar opsi sesuai Flutter (ListConstants)
const KELAS_PERMINTAAN = [
  'VIP A',
  'VIP B',
  'BPJS',
  'Kelas I',
  'Kelas II',
  'Kelas III',
  'ICU',
]
const BIAYA_PERAWATAN = [
  'BPJS',
  'Pribadi',
  'Perusahaan',
  'Askes',
  'Jamsostek',
  'Asuransi',
  'DLL',
]
const SUMBER_PASIEN = ['IGD', 'Poli', 'Pindahan']
const KEADAAN_KELUAR = [
  '1. Sembuh',
  '2. Belum Sembuh/Perbaikan',
  '3. Meninggal Sebelum 48 Jam',
  '4. Meninggal Sesudah 48 Jam',
  '5. Dan Lain-Lain',
]
const CARA_KELUAR = [
  '1. Atas Persetujuan Dokter',
  '2. Pindah Ke Rumah Sakit Lain (Dirujuk)',
  '3. Pindah Ke Rumah Sakit Lain (Permintaan Sendiri)',
  '4. Lari',
  '5. Atas Permintaan Sendiri (APS)',
  '6. Meninggal Dunia',
]

function CeklistRow({
  title,
  list,
  value,
}: {
  title: string
  list: string[]
  value?: string
}) {
  const selected = (value ?? '')
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean)

  return (
    <div className='my-1'>
      <div className='flex items-start'>
        <div className='min-w-[250px]'>
          <p className='text-xs'>{title}</p>
        </div>
        <div className='flex flex-wrap gap-1'>
          {list.map((opt) => {
            const isSelected = selected.includes(opt)
            return (
              <span
                key={opt}
                className={cn(
                  'border border-black px-1 text-[9px]',
                  isSelected ? 'bg-green-200' : 'bg-gray-100 text-gray-500'
                )}
              >
                {opt}
              </span>
            )
          })}
        </div>
      </div>
    </div>
  )
}

export function ReportRingkasanMasuk({
  isReport = false,
  no = '',
  noreg = '',
}: ReportRingkasanMasukProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.ringkasanMasuk, noreg],
    queryFn: () => getRingkasanMasuk(noreg),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result?.no_register == '')
    return <EmptyPlaceholder message='Data tidak ditemukan' />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          RINGKASAN MASUK DAN KELUAR
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}
        {/* Informasi Pasien */}

        <div className='p-2 border border-black space-y-2.5'>
          <TextField title='Nama Pasien' value={result?.nama_pasien} />
          <TextField title='Tanggal Lahir' value={result?.tanggal_lahir} />
          <TextField title='Nomor Rekam Medis' value={result?.no_rm} />
          <TextField title='Nomor Register' value={result?.no_register} />
          <TextField title='Status' value={result?.status} />
          <TextField title='Pendidikan' value={result?.pendidikan} />
          <TextField title='Alamat' value={result?.alamat} />
          <CeklistRow
            title='Kelas Permintaan'
            list={KELAS_PERMINTAAN}
            value={result?.kelas_permintaan}
          />
          <CeklistRow
            title='Biaya Perawatan'
            list={BIAYA_PERAWATAN}
            value={result?.biaya_perawatan}
          />
          <CeklistRow
            title='Sumber Pasien'
            list={SUMBER_PASIEN}
            value={result?.sumber_pasien}
          />
          <CeklistRow
            title='Keadaan Pasien Pada Waktu Keluar'
            list={KEADAAN_KELUAR}
            value={result?.keadaan_keluar}
          />
          <CeklistRow
            title='Cara Keluar'
            list={CARA_KELUAR}
            value={result?.cara_keluar}
          />

          {/*  QR Pendaftar */}
          {result != null && (
            <div className='flex items-center justify-between gap-4 p-2 mb-4'>
              <div className='flex-1' />
              <div className='flex flex-col items-end gap-1'>
                <p className='text-xs text-right'>
                  Pematangsiantar, {formatTanggalV3(result?.tgl_daftar ?? '')}{' '}
                  Pukul : {result?.jam_daftar ?? ''} WIB
                </p>
                <QRCode
                  value={`${result?.nama_pendaftar ?? ''}`}
                  className='h-[100px] w-[100px]'
                />
                <p className='text-xs text-center'>
                  ( {result?.nama_pendaftar ?? ''} )
                </p>
              </div>
            </div>
          )}
          {/*  QR Pendaftar */}
        </div>
      </div>

      {/* Content */}
    </LayoutBorderNo>
  )
}
