export default TableResikoJatuhAnak

function generateName(faktor: string, data: ReportResikoJatuhAnak) {
  return faktor.includes('Jenis Kelamin') &&
    data.jenis_kelamin.includes('Laki-laki')
    ? '2'
    : faktor.includes('Jenis Kelamin') &&
        data.jenis_kelamin.includes('Perempuan')
      ? '1'
      : faktor.includes('Umur') && data.usia.includes('Kurang dari 3 tahun')
        ? '4'
        : faktor.includes('Umur') && data.usia.includes('3 - 7 tahun')
          ? '3'
          : faktor.includes('Umur') && data.usia.includes('7 - 13 tahun')
            ? '2'
            : faktor.includes('Umur') &&
                data.usia.includes('Lebih dari 13 tahun')
              ? '1'
              : faktor.includes('Diagnosa') &&
                  data.diagnosis.includes('Neurologi')
                ? '4'
                : faktor.includes('Diagnosa') &&
                    data.diagnosis.includes(
                      'Gangguan oxigenasi, Respirator, dehidrasi, anemia, anorexia, syncope,',
                    )
                  ? '3'
                  : faktor.includes('Diagnosa') &&
                      data.diagnosis.includes('Gangguan perilaku')
                    ? '2'
                    : faktor.includes('Diagnosa') &&
                        data.diagnosis.includes('Penyakit lain')
                      ? '1'
                      : faktor.includes('Gangguan Kognitif') &&
                          data.gangguan_kognitif.includes(
                            'Keterbatasan daya pikir',
                          )
                        ? '3'
                        : faktor.includes('Gangguan Kognitif') &&
                            data.gangguan_kognitif.includes(
                              'Pelupa, berkurang orientasi sekitar',
                            )
                          ? '2'
                          : faktor.includes('Gangguan Kognitif') &&
                              data.gangguan_kognitif.includes(
                                'Kemampuan Kognitif/ orientasi baik',
                              )
                            ? '1'
                            : faktor.includes('Faktor Lingkungan') &&
                                data.faktor_lingkungan.includes(
                                  'Riwayat jatuh atau bayi / balita yang di tempat tidur (box)',
                                )
                              ? '4'
                              : faktor.includes('Faktor Lingkungan') &&
                                  data.faktor_lingkungan.includes(
                                    'Menggunakan alat bantu (ayunan atau tempat tidur lipat)',
                                  )
                                ? '3'
                                : faktor.includes('Faktor Lingkungan') &&
                                    data.faktor_lingkungan.includes(
                                      'Pasien berada pada tempat tidur standar',
                                    )
                                  ? '2'
                                  : faktor.includes('Faktor Lingkungan') &&
                                      data.faktor_lingkungan.includes(
                                        'Berada di area pasien rawat jalan',
                                      )
                                    ? '1'
                                    : faktor.includes(
                                          'Response terhadap pembedahan, sedasi, dan anestesi',
                                        ) &&
                                        data.respon.includes('Dalam 24 jam')
                                      ? '3'
                                      : faktor.includes(
                                            'Response terhadap pembedahan, sedasi, dan anestesi',
                                          ) &&
                                          data.respon.includes(
                                            '> 48 jam / tanpa response',
                                          )
                                        ? '2'
                                        : faktor.includes(
                                              'Response terhadap pembedahan, sedasi, dan anestesi',
                                            ) &&
                                            data.respon.includes('Dalam 48 jam')
                                          ? '1'
                                          : faktor.includes(
                                                'Penggunaan obat-obatan',
                                              ) &&
                                              data.penggunaan_obat.includes(
                                                'Menggunakan obat lain dari 2 jenis: sedatif, barbiturat, antidepresan, diuretik, narkotik',
                                              )
                                            ? '3'
                                            : faktor.includes(
                                                  'Penggunaan obat-obatan',
                                                ) &&
                                                data.penggunaan_obat.includes(
                                                  'Menggunakan obat-obatan lain / tanpa obat',
                                                )
                                              ? '2'
                                              : faktor.includes(
                                                    'Penggunaan obat-obatan',
                                                  ) &&
                                                  data.penggunaan_obat.includes(
                                                    'Menggunakan 1 jenis obat dari daftar diatas',
                                                  )
                                                ? '1'
                                                : ''
}
