import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { getGeneralConsentRanap } from '@/services/general-consent-ranap'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextField } from './text-field'

interface RekamMedisGeneralConsentRanapProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function RekamMedisGeneralConsentRanap({
  isReport = false,
  noreg = '',
  no,
}: RekamMedisGeneralConsentRanapProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.rekamMedis, noreg],
    queryFn: () => getGeneralConsentRanap(noreg),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo isReport={isReport} no={no}>
      <div className='p-4 text-xs'>
        <h3 className='text-xs font-bold text-center py-3'>
          PERSETUJUAN UMUM / GENERAL CONSENT RAWAT INAP
        </h3>
        <div className='px-5'>
          <p className='text-xs font-bold'>IDENTITAS PASIEN</p>
          <TextField
            title='Nama Pasien'
            value={res?.pasien?.nama_pasien}
            isbool
          />
          <TextField
            title='Tanggal Lahir'
            value={res?.pasien?.tgl_lahir}
            isbool
          />
          <TextField
            title='Nomor Rekam Medis'
            value={res?.pasien?.no_rm}
            isbool
          />
          <TextField title='Alamat' value={res?.pasien?.alamat} isbool />
          <TextField title='No.HP' value={res?.pasien?.no_hp} isbool />
        </div>
        <div className='px-5 py-5'>
          <p className='font-bold'>
            Pasien dan atau Keluarga pasien harus membaca, memahami dan mengisi
            informasi berikut
          </p>
          <p>Yang bertanda tangan dibawah ini :</p>
        </div>
        <div className='px-5 py-5'>
          <TextField title='Nama' value={res?.penanggung_jawab?.nama} />
          <TextField title='Hubungan dengan pasien' value={res?.hubungan} />
          <TextField
            title='Tanggal Lahir'
            value={res?.penanggung_jawab?.tgl_lahir}
          />
          <TextField title='Alamat' value={res?.penanggung_jawab?.alamat} />
          <TextField title='No.HP' value={res?.penanggung_jawab?.no_hp} />
        </div>

        {/* I */}
        <div className='p-5'>
          <div>
            <p>Menyatakan persetujuan</p>
            <p className='font-medium ml-2'>
              I.{' '}
              <strong className='ml-4'>
                Persetujuan untuk perawatan dan pengobatan
              </strong>
            </p>
            <div className='ml-8 flex gap-5'>
              <p>
                Saya menyetujui untuk dirawat diRumah Sakit Harapan sebagai
                pasien rawat inap, karena kondisi saya yang membutuhkan
                perawatan medis setelah diperiksa oleh Dokter jaga{' '}
                {res?.dokter_jaga} Saya mengijinkan Dokter dan profesional
                kesehatan lainya untuk melakukan prosedur diagnose dan
                memberikan pengobatan medis sesuai yang di perlukan dalam
                penilaian profesional mereka.
              </p>
            </div>
            <div className='ml-8  mt-2 flex gap-5'>
              <p>
                Prosedur diagnosa dan perawatan medis tersebut dapat meliputi
                pemeriksaan Radiologi,Tes laboratorium, ECG ,USG , pemasangan
                infus, pemberian obat injeksi / oral dan evaluasi ulang . Saya
                meminta / menyetujui untuk di rawat oleh Dokter :{' '}
                {res?.konsul_ke} sesuai permintaan saya/ keluarga atau sesuai
                jadwal jaga Dokter Spesialis yang telah di tetapkan Rumah sakit
                Harapan dan meminta / bersedia di rawat di Ruang
                :................................................ kelas
                :.................. Persetujuan ini tidak termasuk tindakan
                invasif operasi ataupun tindakan yang beresiko tinggi
                (persetujuan untuk tindakan invasif operasi atau resiko tinggi
                diisi pada formulir khusus) Saya memiliki hak untuk menolak /
                menghentikan semua Tindakan / perawatan medis, dengan mengisi
                pernyataan penolakan Tindakan medis. segala konsekuensi akibat
                dari penolakan / penghentian tersebut menjadi tanggung jawab
                saya / pasien
              </p>
            </div>
          </div>
        </div>
        {/* I */}

        {/* II */}
        <div className='my-[50px]'>
          <p className='font-medium ml-2'>
            II.
            <strong className='ml-4'>PERSETUJUAN PELEPASAN INFORMASI</strong>
          </p>
          <p className='ml-8 mb-2'>
            Saya memahami informasi yang ada di dalam diri saya termasuk
            diagnosa, hasil laboratorium Hasil tes diagnostik yang di gunakan
            untuk perawatan medis, Rumah sakit Harapan akan menjamin
            kerahasiaannya.
          </p>

          <p className='ml-8 mb-2'>
            Saya memberikan wewenang kepada Rumah Sakit Harapan untuk memberikan
            informasi tentang diagnosis , hasil pelayanan dan pengobatan bila di
            perlukan untuk memproses Klaim Asuransi / BPJS / Perusahaan dan atau
            lembaga Pemerintah.
          </p>

          <p className='ml-8 mb-2'>
            Saya memberikan wewenang kepada Rumah sakit Harapan untuk memberikan
            informasi tentang diagnosa, hasil pelayanan dan pengobatan saya
            kepada :
          </p>

          <div className='ml-16'>
            <p>1.</p>
            <p>2.</p>
            <p>3.</p>
          </div>
        </div>
        {/* II */}

        {/* III */}
        <div className='my-[50px]'>
          <p className='font-medium'>
            III.
            <strong className='ml-4'>HAK DAN TANGGUNG JAWAB PASIEN</strong>
          </p>

          <p className='ml-8 mb-2'>
            Saya memiliki hak untuk mengambil bagian dalam keputusan mengenai
            penyakit saya dan dalam hal perawatan medis dan rencana pengobatan .
          </p>
          <p className='ml-8 mb-2'>
            Saya telah mendapat informasi tentang “ Hak dan Tanggung Jawab
            pasien “di Rumah Sakit Harapan melalui leaflet dan banner yang di
            sediakan oleh petugas. Saya memahami bahwa Rumah sakit Harapan Tidak
            bertanggung jawab atas kehilangan barang-barang pribadi dan keluarga
            yang di bawa ke Rumah sakit Harapan .
          </p>
          <p className='ml-8 mb-2'>
            Saya dan keluarga saya memahami sebagai pasien rumah sakit memiliki
            tanggung jawab:
          </p>
          <div className='ml-16'>
            <p className='p-1'>
              1. Mematuhi semua peraturan umum Rumah Sakit Harapan
            </p>
            <p className='p-1'>
              2. Wajib membawa kartu identitas yang benar ( KTP / SIM / Paspor)
              kartu fasilitas kesehatan (BPJS atau asuransi swasta lainya).
            </p>
            <p className='p-1'>
              3. Mematuhi anjuran dokter dan perawat demi kesembuhan penyakit
            </p>
            <p className='p-1'>
              4. Menjaga semua fasilitas yang tersedia di Rumah sakit Harapan
              dengan baik.
            </p>
            <p className='p-1'>
              5. Menjaga ketertiban dan kebersihan di sekitar lingkungan saya
              dirawat ( membuang sampah pada tempatnya , tidak membawa makanan
              ke ruang rawat )
            </p>
            <p className='p-1'>
              6. Ikut menciptakan / menjaga keamanan di Rumah sakit Harapan.
            </p>
            <p className='p-1'>
              7. Wajib mencuci tangan sesuai ajaran perawat ( 5 moment dan 6
              langkah seperti di banner)
            </p>
            <p className='p-1'>
              8. Menjalankan etika batuk / bersin dan meludah seperti yang
              diajarkan perawat
            </p>
            <p className='p-1'>
              9. Tikar tidak boleh dibentangkan setelah jam 6 pagi.
            </p>
            <p className='p-1'>
              10. Ikut membantu perawat tetap menjaga / mendampingi pasien tidak
              meninggalkan pasien.
            </p>
            <p className='p-1'>
              11. Jika pasien pulang Atas Permintaan Sendiri (APS) maka tidak
              ditanggung oleh BPJS Kesehatan, sesuai dengan Peraturan Menteri
              Kesehatan RI No. 28 tahun 2014.
            </p>
          </div>
        </div>

        {/* IV */}
        <div className='my-[50px]'>
          <p className='font-medium ml'>
            IV.
            <strong className='ml-4'>INFORMASI RAWAT INAP</strong>
          </p>
          <p className='ml-8 mb-2'>
            Saya dan keluarga memahami dan akan mematuhi peraturan rawat inap
            Rumah Sakit Harapan
          </p>
          <div className='ml-16'>
            <p className='p-1'>
              1. Jam berkunjung Rumah Sakit Harapan : pagi ( jam 10.00 – 13.00),
              dan sore malam ( jam 17.00-21.00) demi kenyamanan saya selama
              diRumah Sakit Harapan.
            </p>
            <p className='p-1'>
              2. Anggota keluarga yang menunggu saya bersedia untuk selalu
              memakai tanda pendamping pasien yang di berikan Rumah sakit
              Harapan dan menggembalikannya setelah pasien di ijinkan pulang .
            </p>

            <p className='p-1'>
              3. Tidak membawa anak dibawah 12 tahun ke Rumah sakit Harapan .
            </p>
            <p className='p-1'>
              4. Saya /keluarga tidak di perkenankan membawa barang –barang
              berharga ke ruang rawat inap. Bila ada maka sementara dapatdi
              titip di Rumah sakit Harapan .
            </p>
            <p className='p-1'>
              5. Wajib mengingatkan petugas kesehatan akan kebersihan tangan dan
              identifikasi pasien sebelum dan sesudah melayani pasien
            </p>
            <p className='p-1'>
              6. Lingkungan Rumah Sakit Harapan merupakan Area Bebas Rokok
            </p>
          </div>
        </div>

        <div className='my-[50px]'>
          <p className='font-medium'>
            V.
            <strong className='ml-4'>PRIVASI</strong>
          </p>
          <p className='ml-8 mb-2'>
            Saya mengharapkan Rumah sakit Harapan menjaga privasi dan
            kerahasiaan diri saya selama saya dilakukan pemeriksaan oleh Dokter
            atau petugas diagnostik .
          </p>
          <p className='ml-8 mb-2'>
            {' '}
            Saya tidak mengijinkan Rumah sakit Harapan memberikan akses bagi
            keluarga / Handaitolan untuk mengunjungi saya yaitu ( tuliskan nama
            – nama yang tidak bisa mengunjungi )
          </p>

          <div className='ml-16'>
            <p>1.</p>
            <p>2.</p>
            <p>3.</p>
          </div>
        </div>
        {/* V  */}

        {/* VI */}
        <div className='my-[50px]'>
          <p className='font-medium'>
            VI.
            <strong className='ml-4'>INFORMASI BIAYA</strong>
          </p>
          <p className='ml-8 mb-2'>
            Saya memahami semua perincian biaya pelayanan terhadap diri saya
            selama dirawat diRumah sakit Harapan oleh petugas keuangan dan akan
            mematuhi pemenuhan pembayaran biaya tersebut dengan baik
          </p>
          <p className='ml-8 mb-2'>
            Semua persetujuan umum diatas telah saya dan keluarga saya baca dan
            pahami dengan baik, bila ada persetujuan dengan pihak rumah sakit
            lebih lanjut akan di diskusikan di formulir persetujuan tambahan /
            khusus
          </p>
        </div>
        {/* VI */}

        {/* Tanda Tangan */}
        <div className='ml-4'>
          <div className='py-10' />
          <h3 className=' text-center'>Diketahui dan disetujui oleh</h3>

          <div className='flex items-end justify-between'>
            <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
              <p className='font-medium'>Petugas Rumah Sakit</p>
              {res != null ? (
                res.petugas ? (
                  <>
                    <QRCode
                      value={res.petugas}
                      className='h-[100px] w-[100px]'
                    />
                    <p>( {res.petugas} )</p>
                  </>
                ) : (
                  <div className='h-[140px]' />
                )
              ) : (
                <div className='h-[100px]' />
              )}
            </div>
            <div className='w-full text-center items-center flex flex-col gap-4'>
              <p>Pematangsiantar, {res?.tanggal}</p>
              <p className='font-medium'>Pasien/Keluarga</p>
              {res != null && res.penanggung_jawab.nama != '' ? (
                <>
                  {res.penanggung_jawab.nama != null ? (
                    <QRCode
                      value={res.penanggung_jawab.nama}
                      className='h-[100px] w-[100px]'
                    />
                  ) : (
                    <div className='h-[100px]' />
                  )}
                  <p>( {res.penanggung_jawab.nama} )</p>
                </>
              ) : (
                <>
                  {pasien?.nama_pasien != null ? (
                    <QRCode
                      value={pasien.nama_pasien}
                      className='h-[100px] w-[100px]'
                    />
                  ) : (
                    <div className='h-[100px]' />
                  )}
                  <p>( {pasien!.nama_pasien} )</p>
                </>
              )}
            </div>
          </div>
        </div>
        {/* Tanda Tangan */}
      </div>
    </LayoutBorderNo>
  )
}
