import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
// import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { TextTitle } from '@/features/pasien-pulang/rekam-medis/components/text-title'
import { getKonsulen } from '@/services/lembar-konsul-v2'
import { constants } from '@/utils/constants'

import CheckboxList from './components/list-jenis-konsul'
import TitleRow from './components/title-component'

interface LembaranKonsulProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function LembaranKonsul({
  isReport = false,
  no = '',
  noreg = '',
}: LembaranKonsulProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.lembarKonsul, noreg],
    queryFn: () => getKonsulen({ noreg }),
  })

  const res = data?.response != null ? data.response : null
  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res?.konsulen.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div>
        {res?.konsulen.map((item, index) => (
          <div>
            <h1 className='text-center text-black font-semibold mb-2'>
              LEMBARAN KONSUL
            </h1>

            {/* Informasi Pasien */}
            {res != null && (
              <InformasiPasien
                isDynamic={true}
                left={
                  <>
                    <div className='flex items-center justify-start gap-4'>
                      <p className='w-[180px]'>Nama Pasien</p>
                      <p>: {res?.profil_pasien?.nama}</p>
                    </div>
                    <div className='flex items-center justify-start gap-4'>
                      <p className='w-[180px]'>Tanggal Lahir</p>
                      <p>: {res?.profil_pasien?.tgl_lahir}</p>
                    </div>
                    <div className='flex items-center justify-start gap-4'>
                      <p className='w-[180px]'>Nomor Rekam Medis</p>
                      <p>: {res?.profil_pasien?.no_rm}</p>
                    </div>
                  </>
                }
                right={
                  <>
                    <div className='flex items-center justify-start gap-4'>
                      <p className='w-[100px]'>No Reg</p>
                      <p>: {res?.profil_pasien?.no_reg}</p>
                    </div>
                    <div className='flex items-center justify-start gap-4'>
                      <p className='w-[100px]'>Ruangan</p>
                      <p>: {res?.profil_pasien?.ruangan}</p>
                    </div>
                    <div className='flex items-center justify-start gap-4'>
                      <p className='w-[100px]'>Dokter</p>
                      <p>: {item?.dokter_dpjp}</p>
                    </div>
                  </>
                }
              />
            )}
            {/* Informasi Pasien */}

            <hr className='my-2 border-t border-black' />
            <div className='p-2 text-xs mb-20' key={index}>
              {/* Jenis Konsultasi */}
              <div className='flex items-center border border-black p-2 mb-1'>
                <div className='flex-1'>
                  <p className='w-[150px]'>Jenis Konsultasi :</p>
                  <CheckboxList
                    options={[
                      'Mohon Advis',
                      'Rawat Bersama',
                      'Ahli Rawat',
                      'Adakah kelainan dibidang TS',
                      'Preparasi Pre Operasi',
                    ]}
                    value={[item.jenis_konsul]}
                  />
                </div>
              </div>
              {/* Jenis Konsultasi */}

              <div className='flex items-center border border-black p-2 mb-1 w-full'>
                <p className='w-full h-full '>
                  Dokter yang meminta konsul : {item.dokter_dpjp}
                </p>
              </div>

              <div className='flex items-center border border-black p-2 mb-1 w-full'>
                <p className='w-full h-full '>Tanggal/Jam : {item.tanggal}</p>
              </div>

              <div className='flex items-center border border-black p-2 mb-1'>
                <div className='flex-1'>
                  <p className='w-[150px]'>Iktisar Klinik :</p>
                  <h1 className='w-full h-full font-normal text-3xl p-10'>
                    {item.iktisar_klinik}
                  </h1>
                </div>
              </div>

              <div className='border p-2 mb-4'>
                <TextTitle title='Diagnosa Kerja' />
                {/* <DiagnosaTable data={res != null ? res.diagnosa : []} /> */}
              </div>

              <div className='p-2 mb-1 m-2 flex justify-end'>
                <div className='flex flex-col items-center text-center text-xs'>
                  {res != null && item.dokter_dpjp != '' && (
                    <>
                      <QRCode
                        value={item.dokter_dpjp ?? '-'}
                        className='w-[100px] h-[100px]'
                      />
                      <p className='mt-1 font-medium'>
                        ({item.dokter_dpjp ?? '-'})
                      </p>
                    </>
                  )}
                </div>
              </div>

              {/* Jawaban */}
              <div className='border border-black p-2 mb-1 '>
                <p className='font-semibold text-center'>Jawaban </p>

                <TitleRow label='Tanggal/Jam' value={item.tanggal} />
                <TitleRow label='Penemuan' value={item.subjektif} />

                <div className='mb-2'>
                  <div className='flex'>
                    <SimpleColumn
                      head
                      name='Diagnosa'
                      className='p-1 flex-1'
                      className2='text-xs'
                    />
                  </div>
                  <div className='flex '>
                    <SimpleColumn
                      name={
                        item.asesmen && item.asesmen.trim() !== ''
                          ? item.asesmen
                          : ''
                      }
                      className='p-5 flex-1 font-bold font-montserrat'
                      className2='text-xs min-h-[20px]'
                    />
                  </div>
                </div>

                <TitleRow label='Terapi' value={item.plan} />
                <TitleRow label='Anjuran' value={item.instruksi_ppa} />
              </div>

              <div className='p-2 mb-1 m-2 flex justify-end'>
                <div className='flex flex-col items-center text-center text-xs'>
                  {res != null && item.dokter_konsul != '' && (
                    <>
                      <QRCode
                        value={item.dokter_konsul ?? '-'}
                        className='w-[100px] h-[100px]'
                      />
                      <p className='mt-1 font-medium'>
                        ({item.dokter_konsul ?? '-'})
                      </p>
                    </>
                  )}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
      <hr className='my-2 border-t border-gray-300' />
    </LayoutBorderNo>
  )
}
