import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalJam, formatTanggalV3 } from '@/helper/date'
import { getRestrain } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportRestrainProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportRestrain({
  isReport = false,
  no = '',
  noreg = '',
}: ReportRestrainProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.restrain, noreg],
    queryFn: () => getRestrain(noreg),
    enabled: noreg != '',
  })

  const list = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PENGKAJIAN RESTRAIN
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {list.length === 0 ? (
          <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
        ) : (
          <div className='mb-2'>
            {/* Header */}
            <div className='flex'>
              <SimpleColumn
                head
                name='NO'
                className='w-[40px] p-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='KESADARAN'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='TEKANAN DARAH'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='HR'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='TEMP'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='TANGAN KANAN'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='TANGAN KIRI'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='KAKI KANAN'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='KAKI KIRI'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='LUKA'
                className='p-1 flex-1'
                className2='text-[10px]'
              />
              <SimpleColumn
                head
                name='PERAWAT'
                isLast
                className='p-1 flex-1'
                className2='text-[10px]'
              />
            </div>

            {/* Rows */}
            {list.map((item, i) => (
              <div key={item.id_restrain} className='flex'>
                <SimpleColumn
                  name={`${i + 1}`}
                  className='w-[40px] p-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.kesadaran}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.td}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.hr}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.temp}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.tangan_kanan ? '✓' : '✗'}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.tangan_kiri ? '✓' : '✗'}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.kaki_kanan ? '✓' : '✗'}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.kaki_kiri ? '✓' : '✗'}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  name={item.luka ? '✓' : '✗'}
                  className='p-1 flex-1'
                  className2='text-[10px]'
                />
                <SimpleColumn
                  isLast
                  isChild={
                    <div className='flex flex-col items-center gap-1'>
                      <QRCode
                        value={item.nama_user ?? '-'}
                        className='h-[50px] w-[50px]'
                      />
                      <p className='text-[10px]'>{item.nama_user}</p>
                      <p className='text-[10px]'>
                        Perawat {formatTanggalJam(item.insert_dttm)}
                      </p>
                    </div>
                  }
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}
