  const rawNoRm = params.get('no_rm')
  const no_rm = stripQuotes(rawNoRm)

  const { data, isLoading, isError } = useQuery({
    queryKey: ['medis-pasien-sidebar', no_rm],
    queryFn: () => getIdentitasPasien(no_rm),
    enabled: no_rm !== '',
  })

  const pasien = data?.response

