function PilihanRow({
  title,
  list,
  value,
}: {
  title: string
  list: string[]
  value?: string
}) {
  const selected = (value ?? '')
    .split(',')
    .map((v) => v.trim())
    .filter(Boolean)

  return (
    <div className='flex border border-black'>
      <div className='w-[150px] shrink-0 border-r border-black p-1 text-[9px] font-semibold flex items-center'>
        {title}
      </div>
      <div className='flex flex-wrap gap-1 p-1'>
        {list.map((opt) => {
          const isSelected = selected.includes(opt)
          return (
            <span
              key={opt}
              className={cn(
                'border border-black px-1 text-[9px]',
                isSelected ? 'bg-green-200' : 'bg-gray-100 text-gray-500'
              )}
            >
              {opt}
            </span>
          )
        })}
      </div>
    </div>
  )
}

function ValueRow({ title, value }: { title: string; value?: string }) {
  return (
    <div className='flex border border-black'>
      <div className='w-[150px] shrink-0 border-r border-black p-1 text-[9px] font-semibold flex items-center'>
        {title}
      </div>
      <div className='p-1 text-[9px]'>{value ?? '-'}</div>
    </div>
  )
}

export function ReportEdukasiTerintegrasi({
  isReport = false,
  no = 'RM.20',
  no_rm = '',
  noreg = '',
}: ReportEdukasiTerintegrasiProps) {
  const { pasien } = usePasienStore((state) => state)

  const bagian = pasien?.kd_bagian ?? pasien?.bagian ?? ''
  const pelayanan = pasien?.pelayanan ?? ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.edukasiTerintegrasiReport,
      noreg,
      no_rm,
    ],
    queryFn: () =>
      getReportEdukasiTerintegrasi({
        no_rm,
        no_reg: noreg,
        bagian,
        pelayanan,
      }),
    enabled: noreg != '' && no_rm != '',
  })

  const result = data?.response
  const edukasi = result?.edukasi ?? []
  const kebutuhan = result?.kebutuan_edukasi

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR TERINTEGRASI PASIEN/KELUARGA
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        {/* A. ASESSMENT KEBUTUHAN EDUKASI */}
        <h2 className='font-semibold text-[10px] mb-2'>
          A. ASESSMENT KEBUTUHAN EDUKASI
        </h2>
        <div className='border border-black'>
          <p className='p-2 text-[10px] font-semibold border-b border-black'>
            DATA PASIEN
          </p>
          <div>
            <PilihanRow
              title='Tinggal Bersama'
              list={LIST_TINGGAL_BERSAMA}
              value={kebutuhan?.tinggal_bersama}
            />
            <PilihanRow
              title='Hambatan'
              list={LIST_HAMBATAN}
              value={kebutuhan?.hambatan}
            />
            <PilihanRow
              title=''
              list={LIST_HAMBATAN_DETAIL}
              value={kebutuhan?.hambatan_detail}
            />
            <PilihanRow
              title='Edukasi diberikan kepada'
              list={LIST_EDUKASI_KEPADA}
              value={kebutuhan?.edukasi_diberikan_kepada}
            />
            <PilihanRow
              title='Kemampuan Bahasa'
              list={LIST_KEMAMPUAN_BAHASA}
              value={kebutuhan?.kemampuan_bahasa}
            />
            <PilihanRow
              title='Perlu Penerjemah'
              list={LIST_PERLU_PENERJEMAH}
              value={kebutuhan?.perlu_penerjemah}
            />
            <PilihanRow
              title='Baca Dan Tulis'
              list={LIST_BACA_TULIS}
              value={kebutuhan?.baca_dan_tulis}
            />
            <PilihanRow
              title='Agama'
              list={LIST_AGAMA}
              value={kebutuhan?.agama}
            />
            {kebutuhan?.agama == 'Lainnya' && (
              <ValueRow title='' value={kebutuhan?.agama_lainnya} />
            )}
            <PilihanRow
              title='Jenis Kelamin'
              list={LIST_JENIS_KELAMIN}
              value={kebutuhan?.jenis_kelamin}
            />
            <PilihanRow
              title='Pendidikan'
              list={LIST_PENDIDIKAN}
              value={kebutuhan?.pendidikan}
            />
            <PilihanRow
              title='Kepercayaan Lainnya'
              list={LIST_KEPERCAYAAN_LAINNYA}
              value={kebutuhan?.kepercayaan_lainnya}
            />
            <PilihanRow
              title='Kesediaan Menerima Edukasi'
              list={LIST_KESEDIAAN}
              value={kebutuhan?.kesediaan_menerima_edukasi}
            />
            <PilihanRow
              title='Cara Edukasi'
              list={LIST_CARA_EDUKASI}
              value={kebutuhan?.cara_edukasi}
            />
            <PilihanRow
              title='Kebutuhan Edukasi'
              list={LIST_KEBUTUHAN_EDUKASI}
              value={kebutuhan?.kebutuhan_edukasi}
            />
          </div>
        </div>

        {/* B. PELAKSANAAN EDUKASI */}
        <h2 className='font-semibold text-[10px] mt-4 mb-2'>
          B. PELAKSANAAN EDUKASI
        </h2>
        <p className='text-[10px] mb-2'>
          Pasien telah diberi Informasi sebagai berikut :
        </p>

        {edukasi.length === 0 ? (
          <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
        ) : (
          <div className='mb-2'>
            <div className='flex'>
              <SimpleColumn
                head
                name='NO.'
                className='w-[30px] p-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Tgl & Jam Edukasi'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Materi Edukasi Berdasarkan Kebutuhan'
                className='p-1 flex-[2]'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Metode'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Lama Edukasi (Menit)'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Hasil Verifikasi'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Tgl Re-Edukasi/Re-Demontrasi'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Pemberi Informasi'
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                head
                name='Penerima Informasi'
                isLast
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
            {edukasi.map((item, i) => (
              <div key={item.id_edukasi ?? i} className='flex'>
                <SimpleColumn
                  name={`${i + 1}`}
                  className='w-[30px] p-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={`${formatTanggalV3(
                    item.insert_dttm?.substring(0, 10)
                  )} ${item.insert_dttm?.substring(11, 19)}`}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={item.informasi}
                  className='p-1 flex-[2]'
                  className2='text-[9px] text-left'
                />
                <SimpleColumn
                  name={item.metode}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={item.lama_edukasi}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={item.evaluasi}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  name={item.tgl_edukasi}
                  className='p-1 flex-1'
                  className2='text-[9px]'
                />
                <SimpleColumn
                  isChild={
                    item.pemberi_informasi ? (
                      <div className='flex flex-col items-center gap-1'>
                        <QRCode
                          value={item.pemberi_informasi}
                          className='h-[40px] w-[40px]'
                        />
                        <p className='text-[9px]'>{item.pemberi_informasi}</p>
                      </div>
                    ) : (
                      <p className='text-[9px]'>-</p>
                    )
                  }
                  className='p-1 flex-1'
                />
                <SimpleColumn
                  isLast
                  isChild={
                    item.penerima_informasi ? (
                      <div className='flex flex-col items-center gap-1'>
                        <QRCode
                          value={item.penerima_informasi}
                          className='h-[40px] w-[40px]'
                        />
                        <p className='text-[9px]'>{item.penerima_informasi}</p>
                      </div>
                    ) : (
                      <p className='text-[9px]'>-</p>
                    )
                  }
                  className='p-1 flex-1'
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </LayoutBorderNo>
  )
}
