import type { RegisterPasien, ReportGeneralConsentRajal, Response } from '@/type'

import {  post } from './api'
import { get as get3, } from './api-3'

const getGeneralConsenRAJAL = async (
    no_reg: string,
    no_rm: string,
): Promise<Response<ReportGeneralConsentRajal>> => {
    const response = await get3(`/v1/general-consent-rajal/${no_reg}/${no_rm}`)

    return response.data
}

const getRegisterPasien = async ({
    no_rm,
}: {
    no_rm: string
}): Promise<Response<RegisterPasien[]>> => {
    const response = await post(`/v1/register-pasien`, { no_rm: String(no_rm) })

    return response.data
}

export { getGeneralConsenRAJAL, getRegisterPasien }
