export default TableResikoJatuhMorse

function generateScore(faktor: string, data: ResikoJatuhMorse): number {
  switch (faktor) {
    case 'Riwayat Jatuh':
      return data.r_jatuh === 'Ya' ? 25 : 0
    case 'Diagnosis Sekunder\n(>= diagnosis medis)':
      return data.diagnosis === 'Ya' ? 15 : 0
    case 'Bantuan Ambulansi':
      return data.ambulasi === 'Furniture : dinding, meja, kursi, lemari'
        ? 30
        : data.ambulasi === 'Kruk / Tongkat / Walker'
          ? 15
          : 0
    case 'Terapi IV / anti koagulan':
      return data.terapi === 'Terapi intravena terus menerus' ? 20 : 0
    case 'Terapasang infuse':
      return data.terpasang_infuse === 'Ya' ? 20 : 0
    case 'Gaya berjalan':
      return data.gaya_berjalan === 'Terganggu'
        ? 20
        : data.gaya_berjalan === 'Lemah'
          ? 10
          : 0
    case 'Status Mental':
      return data.status_mental ===
        'Sering lupa akan keterbatasan yang dimiliki'
        ? 15
        : 0
    default:
      return 0
  }
}
