import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalIndonesia } from '@/helper/date'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { Kartuobservasi, getKartuObservasi } from './observasi'

interface KartuObservasiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

const th = 'border border-black px-2 py-2 font-bold text-center align-middle'
const td = 'border border-black px-2 py-1 text-center align-middle'

export default function KartuObservasi({
  isReport = false,
  noreg = '',
  no = '',
}: KartuObservasiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.kartuObservasi, noreg],
    queryFn: () => getKartuObservasi({ noreg: noreg }),
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />

  // res diasumsikan array baris (KartuObservasiRow[]); sesuaikan jika API
  // membungkusnya dalam properti lain, mis. res?.dat
  const rows: Kartuobservasi[] = Array.isArray(res) ? res : []

  return (
    <LayoutBorderNo isReport={isReport} no={no}>
      <div className='p-4 text-xs'>
        <h3 className='font-bold text-center py-3'>KARTU OBSERVASI 24 JAM</h3>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            ruangan={pasien.bagian}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}
        {/* Informasi Pasien */}

        <div className='overflow-x-auto mt-1'>
          <table className='border-collapse w-full text-sm'>
            <thead>
              {/* Row 1 */}
              <tr>
                <th rowSpan={3} className={th}>
                  JAM
                </th>
                <th rowSpan={3} className={th}>
                  T
                </th>
                <th rowSpan={3} className={th}>
                  N
                </th>
                <th rowSpan={3} className={th}>
                  P
                </th>
                <th rowSpan={3} className={th}>
                  S
                </th>
                <th rowSpan={3} className={th}>
                  CVP
                </th>
                <th rowSpan={3} className={th}>
                  EKG
                </th>
                <th colSpan={4} className={th}>
                  PUPIL
                </th>
                <th rowSpan={3} className={th}>
                  GERAK
                  <br />
                  ANGGOTA
                  <br />
                  BADAN
                </th>
                <th rowSpan={3} className={th}>
                  KESADARAN
                </th>
                <th rowSpan={3} className={th}>
                  SPUTUM
                  <br />
                  WARNA
                </th>
                <th rowSpan={3} className={th}>
                  ISI CUP
                </th>
                <th rowSpan={3} className={th}>
                  KETERANGAN
                </th>
              </tr>
              {/* Row 2 */}
              <tr>
                <th colSpan={2} className={th}>
                  UKURAN
                </th>
                <th colSpan={2} className={th}>
                  REDAKSI
                </th>
              </tr>
              {/* Row 3 */}
              <tr>
                <th className={th}>KI</th>
                <th className={th}>KA</th>
                <th className={th}>KI</th>
                <th className={th}>KA</th>
              </tr>
            </thead>

            <tbody>
              {rows.length === 0 ? (
                <tr>
                  <td colSpan={16} className={`${td} py-4 text-gray-400`}>
                    Belum ada data observasi
                  </td>
                </tr>
              ) : (
                rows.map((row, rowIndex) => (
                  <tr key={rowIndex}>
                    <td className={td}>{formatTanggalIndonesia(row.jam)}</td>
                    <td className={td}>{row.t}</td>
                    <td className={td}>{row.n}</td>
                    <td className={td}>{row.p}</td>
                    <td className={td}>{row.s}</td>
                    <td className={td}>{row.cvp}</td>
                    <td className={td}>{row.ekg}</td>
                    <td className={td}>{row.pupil_kiri}</td>
                    <td className={td}>{row.pupil_kanan}</td>
                    <td className={td}>{row.redaksi_kiri}</td>
                    <td className={td}>{row.redaksi_kanan}</td>
                    <td className={td}>{row.anggota_badan}</td>
                    <td className={td}>{row.kesadaran}</td>
                    <td className={td}>{row.sputum_warna}</td>
                    <td className={td}>{row.isi_cup}</td>
                    <td className={td}>{row.keterangan}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
