interface Dokter {
  nama: string
  ttd?: string | null
}

interface SignatureBlockProps {
  title: string
  dokter: Dokter
}

export default function SignatureBlock({ title, dokter }: SignatureBlockProps) {
  return (
    <div className='flex flex-1 flex-col items-center gap-2 rounded-sm border border-slate-300 px-4 py-5 text-center'>
      <span className='text-sm font-semibold text-slate-700'>{title}</span>
      <div className='flex h-20 w-full items-center justify-center'>
        {dokter.ttd ? (
          <img
            src={dokter.ttd}
            alt={`Tanda tangan ${dokter.nama}`}
            className='max-h-20 object-contain'
          />
        ) : (
          <span className='text-xs text-slate-300'>(tanda tangan)</span>
        )}
      </div>
      <span className='border-t border-slate-400 pt-1 text-sm font-medium text-slate-900'>
        ( {dokter.nama || '-'} )
      </span>
    </div>
  )
}

export type { Dokter, SignatureBlockProps }
