import { useMemo, useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { SimpleColumnPPA } from '@/components/simple-column-ppa'
import { TandaTangan } from '@/components/tanda-tangan'
import { cn } from '@/lib/utils'
import { getReportCpptByNoreg } from '@/services/cppt'
import { useAuthStore } from '@/store/auth.store'
import { usePasienStore } from '@/store/pasien.store'
import { CpptByNoreg } from '@/type'
import { constants } from '@/utils/constants'

type SortOrder = 'asc' | 'desc'

const parseTanggal = (s: string): number => {
  if (s == null || s === '') return 0

  // unix timestamp (seconds / milliseconds)
  if (/^\d{10}$/.test(s)) return +s * 1000
  if (/^\d{13}$/.test(s)) return +s

  // Normalize the space separator to 'T' so it is a valid ISO string in every
  // browser (some engines reject "YYYY-MM-DD HH:mm:ss" with a space).
  const t = new Date(s.trim().replace(' ', 'T')).getTime()
  if (Number.isNaN(t) === false) return t

  const toTime = (y: number, mo: number, d: number, h = 0, mi = 0, se = 0) =>
    new Date(y, mo - 1, d, h, mi, se).getTime()

  // YYYY[-/.]MM[-/.]DD [HH:mm[:ss]]
  let m = s.match(
    /(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/
  )
  if (m) {
    return toTime(
      +m[1],
      +m[2],
      +m[3],
      m[4] ? +m[4] : 0,
      m[5] ? +m[5] : 0,
      m[6] ? +m[6] : 0
    )
  }

  // DD[-/.]MM[-/.]YYYY [HH:mm[:ss]]
  m = s.match(
    /(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/
  )
  if (m) {
    return toTime(
      +m[3],
      +m[2],
      +m[1],
      m[4] ? +m[4] : 0,
      m[5] ? +m[5] : 0,
      m[6] ? +m[6] : 0
    )
  }

  // Indonesian text: "18 Agustus 2026 10:30:00"
  const bulan: Record<string, number> = {
    januari: 1,
    februari: 2,
    maret: 3,
    april: 4,
    mei: 5,
    juni: 6,
    juli: 7,
    agustus: 8,
    september: 9,
    oktober: 10,
    november: 11,
    desember: 12,
  }
  m = s.match(
    /(\d{1,2})[\s\-./]+([A-Za-z]+)[\s\-./]+(\d{4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/
  )
  if (m && bulan[m[2].toLowerCase()]) {
    return toTime(
      +m[3],
      bulan[m[2].toLowerCase()],
      +m[1],
      m[4] ? +m[4] : 0,
      m[5] ? +m[5] : 0,
      m[6] ? +m[6] : 0
    )
  }

  return 0
}

interface CPPTResumeProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function CPPTResume({
  isReport = false,
  noreg = '',
  no = '',
}: CPPTResumeProps) {
  const { pasien } = usePasienStore((state) => state)
  const { user } = useAuthStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.pasien.cppt.report, noreg],
    queryFn: () => getReportCpptByNoreg(noreg),
  })

  const result = data?.response != null ? data?.response : ({} as CpptByNoreg)

  const [sortOrder, setSortOrder] = useState<SortOrder>('desc')

  const sortedCppt = useMemo(() => {
    return (result.cppt ?? [])
      .map((item, index) => ({ item, index }))
      .sort((a, b) => {
        const diff = parseTanggal(a.item.tanggal) - parseTanggal(b.item.tanggal)
        // keep stable order for items with equal/unparseable dates
        if (diff !== 0) return sortOrder === 'asc' ? diff : -diff
        return a.index - b.index
      })
      .map(({ item }) => item)
  }, [result.cppt, sortOrder])

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          CATATAN PERKEMBANGAN PASIEN TERINTEGRASI SOAP
        </h1>

        {/* Informasi Pasien */}
        {result.profil_pasien != null && (
          <InformasiPasien
            nama={result.profil_pasien.nama}
            noRM={pasien?.no_rm ?? ''}
            ruangan={result.profil_pasien.ruangan}
            tanggalLahir={result.profil_pasien.tgl_lahir}
            jk={result.profil_pasien.jenis_kelamin}
          />
        )}
        {/* Informasi Pasien */}

        <div>
          {/* Sort Controls */}
          <div className='flex items-center justify-end gap-1 mb-1 print:hidden'>
            <span className='text-[10px] text-gray-500 mr-1'>
              Urutkan tanggal:
            </span>
            <button
              type='button'
              onClick={() => setSortOrder('asc')}
              className={cn(
                'text-[10px] px-2 py-1 rounded-md border transition-colors',
                sortOrder === 'asc'
                  ? 'bg-primaryColor text-white border-primaryColor'
                  : 'border-gray-300 text-gray-600 hover:bg-gray-100'
              )}
            >
              ▲ Awal → Akhir
            </button>
            <button
              type='button'
              onClick={() => setSortOrder('desc')}
              className={cn(
                'text-[10px] px-2 py-1 rounded-md border transition-colors',
                sortOrder === 'desc'
                  ? 'bg-primaryColor text-white border-primaryColor'
                  : 'border-gray-300 text-gray-600 hover:bg-gray-100'
              )}
            >
              ▼ Akhir → Awal
            </button>
          </div>
          {/* Sort Controls */}

          {/* Header */}
          <div className='flex text-xs'>
            <SimpleColumn head name='Tanggal & Jam' className='w-[100px]' />
            <SimpleColumn
              head
              name='Professional Pemberi Asuhan'
              className='flex-[0.5]'
            />
            <SimpleColumn head name='Hasil Asesmen' className='flex-1' />
            <SimpleColumn head name='Instruksi PPA' className='flex-[0.5]' />
            <SimpleColumn
              head
              name='Verifikasi DPJP'
              isLast={isReport || pasien?.bagian !== user?.bagian}
              className='flex-[0.5]'
            />
            {!isReport && pasien?.bagian === user?.bagian && (
              <SimpleColumn head name='Action' isLast className='w-[100px]' />
            )}
          </div>

          {sortedCppt.length > 0 &&
            sortedCppt.map((item) => (
              <div className='flex text-xs' key={item.id}>
                <SimpleColumn name={item.tanggal} className='w-[100px]' />

                <SimpleColumnPPA
                  namePPA={item.kelompok}
                  name={item.pemberi_asuhan}
                  className='flex-[0.5]'
                  hasQR
                />

                <SimpleColumn
                  isChild={
                    <>
                      {item.metode == 'sbar' ? (
                        <>
                          <Item k='S' value={item.situation} />
                          <Item k='B' value={item.background} />
                          <Item k='A' value={item.asesmen} />
                          <Item k='R' value={item.recommendation} />
                        </>
                      ) : (
                        <>
                          <Item k='S' value={item.subjektif} />
                          <Item k='O' value={item.objektif} />
                          <Item k='A' value={item.asesmen} />
                          <Item k='P' value={item.plan} />
                        </>
                      )}

                      <TandaTangan
                        name={item.hand_over}
                        size={100}
                        imageSrc={
                          item.hand_over_file !== ''
                            ? `${import.meta.env.VITE_BASE_API_URL}/app/images/handover/${item.hand_over_file}`
                            : undefined
                        }
                        className='flex-1 [&_img]:w-full [&_img]:max-h-32 [&_img]:object-contain'
                      />
                    </>
                  }
                  className='justify-start items-start flex-1'
                  className2='text-left'
                />
                <SimpleColumn
                  name={item.instruksi_ppa}
                  className='flex-[0.5]'
                />
                {item.metode !== 'sbar' ? (
                  <SimpleColumn
                    name={item.dpjp}
                    hasQR
                    isLast={isReport || pasien?.bagian !== user?.bagian}
                    className='flex-[0.5]'
                  />
                ) : (
                  <SimpleColumn
                    name={item.dpjp}
                    isLast={isReport}
                    hasQR
                    className='flex-[0.5]'
                  />
                )}
              </div>
            ))}
          {/* Body */}
        </div>
      </div>
      {/* Content */}
    </LayoutBorderNo>
  )
}

const Item = ({ k, value }: { k: string; value: string }) => {
  return (
    <span className='flex flex-shrink-0 gap-1'>
      <strong>{k}</strong> :{' '}
      <p className='text-xs text-black text-left'>{value}</p>
    </span>
  )
}
