// 1. Definisikan tipe untuk data pemeriksaan
interface ExamData {
  [key: string]: string
}

// 2. Definisikan tipe untuk props komponen TableColumn
interface TableColumnProps {
  items: [string, string][]
}

const PhysicalExamReport = ({
  data,
  examDate,
}: {
  data: ExamData
  patientName?: string
  examDate?: string
}) => {
  const entries = Object.entries(data)
  const half = Math.ceil(entries.length / 2)
  const leftColumn = entries.slice(0, half)
  const rightColumn = entries.slice(half)

  // 3. Berikan tipe pada parameter 'items'
  const TableColumn = ({ items }: TableColumnProps) => (
    <div className='flex-1'>
      <table className='w-full border-collapse border border-black text-sm'>
        <tbody>
          {items.map(([key, value]) => (
            <tr key={key} className='border border-black'>
              <td className='p-2 font-medium w-1/3 border-r border-black capitalize'>
                {key.replace(/_/g, ' ')}
              </td>
              <td className='p-2'>: {value}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )

  return (
    <div className='p-8 bg-white text-gray-800'>
      <div className='flex flex-col md:flex-row gap-4 mb-8'>
        <TableColumn items={leftColumn} />
        <TableColumn items={rightColumn} />
      </div>
      <div className='flex justify-between items-start mt-10 text-sm'>
        <div>
          <p>Hasil pemeriksaan yang dibawa pasien</p>
        </div>
        <div className='text-right'>
          <p>Tanggal Periksa : {examDate || '....................'}</p>
        </div>
      </div>
    </div>
  )
}

export default PhysicalExamReport
