import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { formatTanggalV3 } from '@/helper/date'
import { RekonsiliasiObatPulang } from '@/models/rekonsiliasi-obat-pulang'
import { getRekonsiliasiObatPulang } from '@/services/daftar-obat-harian'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { RekonsiliasiObatPulangTable } from './rekonsiliasi-obat-pulang-table'

// import { Edit } from 'lucide-react'

interface ReportRekonsiliasiObatPulangProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function ReportRekonsiliasiObatPulang({
  isReport = false,
  noreg = '',
  no = '',
}: ReportRekonsiliasiObatPulangProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.rekonsiliasiObatPulang, noreg],
    queryFn: () => getRekonsiliasiObatPulang({ noreg: noreg }),
  })

  const result =
    data?.response != null ? data?.response : ({} as RekonsiliasiObatPulang)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.obat.length === 0)
    return <p className='text-center'>Data tidak ditemukan</p>

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          REKONSILIASI OBAT SAAT PASIEN PULANG
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}
        {/* Informasi Pasien */}
      </div>

      <div className='p-2'>
        <div className='flex items-center justify-between text-xs mb-2'>
          <p>Tanggal: {formatTanggalV3(result.tanggal) ?? ''}</p>
          <p>Jam: {result.jam ?? ''} WIB</p>
        </div>
        <RekonsiliasiObatPulangTable data={result.obat} />
      </div>

      <div className='flex p-2 items-start justify-around mt-[100px]'>
        <div className='flex flex-col gap-4 items-center text-center text-xs'>
          {result.apoteker != null && result.apoteker.ttd == '' ? (
            <>
              <p className='text-sm'>Apoteker</p>
              <QRCode
                value={result.apoteker.nama ?? '-'}
                className='w-[100px] h-[100px]'
              />
              <p className=''>({result.apoteker.nama ?? '-'})</p>
            </>
          ) : (
            <>
              <p className='text-sm'>Apoteker</p>

              <img
                alt='ttd'
                src={`${import.meta.env.VITE_BASE_API_URL}/app/images/rekonsiliasi/${result.apoteker.ttd}`}
                className='w-[100px] h-[100px]'
              />
              <p className=''>({result.apoteker.nama ?? '-'})</p>
            </>
          )}
        </div>{' '}
        <div className='flex flex-col gap-4 items-center text-center text-xs'>
          {result.apoteker != null && result.pasien.ttd == '' ? (
            <>
              <p className='text-sm'>Pasien / Keluarga</p>
              <QRCode
                value={result.pasien.nama ?? '-'}
                className='w-[100px] h-[100px]'
              />
              <p className=''>({result.pasien.nama ?? '-'})</p>
            </>
          ) : (
            <>
              <p className='text-sm'>Pasien / Keluarga</p>

              <img
                alt='ttd'
                src={`${import.meta.env.VITE_BASE_API_URL}/app/images/rekonsiliasi/${result.pasien.ttd}`}
                className='w-[100px] h-[100px]'
              />
              <p className=''>({result.pasien.nama ?? '-'})</p>
            </>
          )}
        </div>
      </div>

      {/* Content */}
    </LayoutBorderNo>
  )
}
