import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { formatTanggalV3 } from '@/helper/date'
import { cn } from '@/lib/utils'
import { getAsuhanGizi } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportAsuhanGiziProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

function GreyTitle({ title }: { title: string }) {
  return (
    <div className='bg-gray-300 px-2 py-1 my-2'>
      <p className='text-[10px] font-semibold text-center'>{title}</p>
    </div>
  )
}

function TextBox({ value }: { value?: string }) {
  return (
    <div className='border border-black bg-gray-50 p-2 min-h-[60px]'>
      <p className='text-[10px] whitespace-pre-wrap'>{value ?? ''}</p>
    </div>
  )
}

export function ReportAsuhanGizi({
  isReport = false,
  no = 'RM. RI 17',
  noreg = '',
}: ReportAsuhanGiziProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asuhanGizi, noreg],
    queryFn: () => getAsuhanGizi(noreg),
    enabled: noreg != '',
  })

  const result = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (
    result == null ||
    (result.tanggal == '' &&
      result.jam == '' &&
      result.nama_ahli_gizi == '' &&
      result.diagnosis_gizi == '')
  )
    return (
      <LayoutBorderNo no={no} isReport={isReport}>
        <p className='text-center text-sm p-4'>Data tidak ditemukan</p>
      </LayoutBorderNo>
    )

  const fisik = result.fisik_gizi

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR ASUHAN GIZI
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien ?? ''}
            noRM={pasien?.no_rm ?? ''}
            ruangan={pasien.bagian ?? ''}
            tanggalLahir={formatTanggalV3(pasien.tanggal_lahir) ?? ''}
            jk={pasien.jenis_kelamin ?? ''}
          />
        )}

        <p className='text-[10px] mb-2'>
          Tanggal : {formatTanggalV3(result.tanggal) ?? result.tanggal}
          {result.jam ? ` - Jam : ${result.jam}` : ''}
        </p>

        {/* DIAGNOSA MEDIS */}
        <p className='text-[10px] font-semibold mb-1'>DIAGNOSA MEDIS</p>
        <div className='mb-2'>
          <div className='flex'>
            <SimpleColumn
              head
              name='NO.'
              className='w-[30px] p-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='KODE'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Deskripsi'
              className='p-1 flex-1'
              className2='text-[9px]'
            />
            <SimpleColumn
              head
              name='Diagnosa'
              isLast
              className='p-1 flex-1'
              className2='text-[9px]'
            />
          </div>
          {result.diagnosa?.map((d, i) => (
            <div key={i} className='flex'>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[30px] p-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={d.diagnosa}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
              <SimpleColumn
                name={d.description}
                className='p-1 flex-1'
                className2='text-[9px] text-left'
              />
              <SimpleColumn
                isLast
                name={d.type?.toUpperCase()}
                className='p-1 flex-1'
                className2='text-[9px]'
              />
            </div>
          ))}
        </div>

        {/* ASSESMEN GIZI */}
        <GreyTitle title='ASSESMEN GIZI' />
        <p className='text-[10px] mb-1'>Anthropometri</p>
        <div className='border border-black mb-1'>
          <div className='flex border-b border-black'>
            <div className='flex-1 p-1 text-[9px]'>
              Umur : <span className='font-semibold'>{result.umur}</span>
            </div>
            <div className='flex-1 p-1 text-[9px] border-l border-black' />
          </div>
          <div className='flex border-b border-black'>
            <div className='flex-1 p-1 text-[9px]'>
              BB : <span className='font-semibold'>{fisik?.bb}</span> Kg
            </div>
            <div className='flex-1 p-1 text-[9px] border-l border-black'>
              Lingkar Lengan Atas :{' '}
              <span className='font-semibold'>{fisik?.lla}</span> cm
            </div>
          </div>
          <div className='flex border-b border-black'>
            <div className='flex-1 p-1 text-[9px]'>
              TB : <span className='font-semibold'>{fisik?.tb}</span> Cm
            </div>
            <div className='flex-1 p-1 text-[9px] border-l border-black'>
              Lingkar Lutut : <span className='font-semibold'>{fisik?.lt}</span>{' '}
              cm
            </div>
          </div>
          <div className='flex'>
            <div className='flex-1 p-1 text-[9px]'>
              IMT : <span className='font-semibold'>{fisik?.imt}</span> Kg/cm2
            </div>
            <div className='flex-1 p-1 text-[9px] border-l border-black'>
              Kategori :{' '}
              <span className='font-semibold'>{fisik?.kategori}</span>
            </div>
          </div>
        </div>

        <GreyTitle title='Biokimia' />
        <TextBox value={result.biokimia} />

        <GreyTitle title='Klinik/Fisik' />
        <TextBox value={result.klinik_fisik} />

        {/* RIWAYAT GIZI */}
        <GreyTitle title='RIWAYAT GIZI' />
        <p className='text-[10px] mb-1'>Alergi Makanan</p>
        <div className='flex flex-wrap gap-1 mb-2'>
          {result.alergi_makan?.map((a, i) => (
            <div key={i} className='border border-black px-1 py-0.5 text-[9px]'>
              <span>{a.deskripsi}</span>
              <span
                className={cn(
                  'ml-2 border border-black px-1',
                  a.hasil == 'YA' ? 'bg-green-200' : 'bg-gray-100'
                )}
              >
                YA
              </span>
              <span
                className={cn(
                  'ml-1 border border-black px-1',
                  a.hasil == 'TIDAK' ? 'bg-green-200' : 'bg-gray-100'
                )}
              >
                TIDAK
              </span>
            </div>
          ))}
        </div>

        <GreyTitle title='Pola Makan' />
        <TextBox value={result.pola_makan} />

        <GreyTitle title='Riwayat Personal' />
        <TextBox value={result.riwayat_personal} />

        <GreyTitle title='Diagnosa Gizi' />
        <TextBox value={result.diagnosis_gizi} />

        <GreyTitle title='Intervensi Gizi' />
        <TextBox value={result.intervensi_gizi} />

        <GreyTitle title='Monitoring & Evaluasi' />
        <TextBox value={result.monitoring_evaluasi} />

        {/* Tanda tangan Ahli Gizi */}
        <div className='flex flex-col items-center gap-1 p-3 text-center text-xs mt-4'>
          <p className='font-semibold'>Ahli Gizi</p>
          <QRCode
            value={result.nama_ahli_gizi ?? '-'}
            className='h-[70px] w-[70px]'
          />
          <p>( {result.nama_ahli_gizi ?? ''} )</p>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
